class Client:
    def __init__(self, args=['--stdio'], env_extra=None, cwd='/tmp/proj', exe='/workspace/executable', autorespond=True, home='/tmp/h3'):
        env=dict(os.environ); env['HOME']=home
        if env_extra: env.update(env_extra)
        self.p=subprocess.Popen([exe]+args,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=env,cwd=cwd)
        self.msgs=[]; self.raw=b''
        self.t0=time.time()
        self.autorespond=autorespond
        self.lock=threading.Lock()
        self.rt=threading.Thread(target=self._reader,daemon=True); self.rt.start()
        self.et=threading.Thread(target=self._errreader,daemon=True); self.et.start()
        self.err=b''
    def _errreader(self):
        while True:
            d=self.p.stderr.readline()
            if not d: break
            self.err+=d
            sys.stderr.write("[%6.2f] ERR %s"%(time.time()-self.t0,d.decode(errors='replace')))
    def _reader(self):
        buf=b''
        while True:
            d=self.p.stdout.read1(65536) if hasattr(self.p.stdout,'read1') else self.p.stdout.read(1)
            if not d: break
            buf+=d
            while True:
                i=buf.find(b'\r\n\r\n')
                if i<0: break
                hdr=buf[:i].decode()
                ln=None
                for h in hdr.split('\r\n'):
                    if h.lower().startswith('content-length:'):
                        ln=int(h.split(':')[1].strip())
                if ln is None: break
                if len(buf)<i+4+ln: break
                body=buf[i+4:i+4+ln]; buf=buf[i+4+ln:]
                try:
                    m=json.loads(body)
                except Exception as e:
                    m={'_raw':body.decode(errors='replace')}
                t=time.time()-self.t0
                self.msgs.append((t,m))
                s=json.dumps(m)
                print("[%6.2f] <-- %s"%(t, s if len(s)<600 else s[:600]+'...(%d)'%len(s)))
                sys.stdout.flush()
                if self.autorespond and 'method' in m and 'id' in m:
                    self.respond(m['id'], None)
    def send(self,obj):
        b=json.dumps(obj).encode()
        print("[%6.2f] --> %s"%(time.time()-self.t0, json.dumps(obj)[:300])); sys.stdout.flush()
        with self.lock:
            try:
                self.p.stdin.write(b"Content-Length: %d\r\n\r\n"%len(b)+b); self.p.stdin.flush()
            except BrokenPipeError:
                print("broken pipe")
    def sendraw(self,b):
        with self.lock:
            self.p.stdin.write(b); self.p.stdin.flush()
    def respond(self,id,result):
        self.send({"jsonrpc":"2.0","id":id,"result":result})
    def request(self,id,method,params=None):
        m={"jsonrpc":"2.0","id":id,"method":method}
        if params is not None: m["params"]=params
        self.send(m)
    def notify(self,method,params=None):
        m={"jsonrpc":"2.0","method":method}
        if params is not None: m["params"]=params
        self.send(m)
    def wait_for(self, pred, timeout=30):
        t=time.time()
        while time.time()-t<timeout:
            for (tt,m) in self.msgs:
                if pred(m): return m
            time.sleep(0.05)
        return None
    def wait_response(self,id,timeout=30):
        return self.wait_for(lambda m: m.get('id')==id and 'method' not in m, timeout)
    def finish(self,timeout=10):
        try:
            self.p.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            print("TIMEOUT killing"); self.p.kill(); self.p.wait()
        time.sleep(0.2)
        print("RC", self.p.returncode)
        return self.p.returncode
    def close_stdin(self):
        self.p.stdin.close()

def init_params(root='file:///tmp/proj', folders=True, caps=None):
    p={"processId":None,"rootUri":root,"capabilities":caps or {"window":{"workDoneProgress":True}}}
    if folders and root: p["workspaceFolders"]=[{"uri":root,"name":"proj"}]
    return p
