        c.request(100+i,"rustowl/cursor",{"position":{"line":l,"character":ch},"document":{"uri":uri}})
        r=c.wait_response(100+i)
        results.append(r.get('result') if r else r)
    c.request(10,"shutdown"); c.wait_response(10); c.notify("exit"); time.sleep(0.3); c.close_stdin(); c.finish()
    return results
