        s=d['range']['start']; e=d['range']['end']
        out.append("%s[%d,%d]%s local=%s %r"%(d['type'], off(s['line'],s['character']), off(e['line'],e['character']), ' OVL' if d['overlapped'] else '', (d['local']['fn_id'],d['local']['id']), d['hover_text']))
    return "status=%s is_analyzed=%s\n   "%(res.get('status'),res.get('is_analyzed'))+"\n   ".join(out)
