//! simple_logger style logging to stderr.

use std::io::{IsTerminal, Write};
use std::sync::atomic::{AtomicU8, Ordering};
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

static MAX_LEVEL: AtomicU8 = AtomicU8::new(0);
static COLORS: AtomicU8 = AtomicU8::new(0);
static LOCK: Mutex<()> = Mutex::new(());

/// Initialize the logger with a default level filter (0 = off .. 5 = trace).
/// `RUST_LOG` overrides the default when it is a valid level name.
pub fn init(default: u8) {
    let mut level = default;
    if let Ok(v) = std::env::var("RUST_LOG") {
        let l = v.to_ascii_lowercase();
        let parsed = match l.as_str() {
            "off" => Some(0),
            "error" => Some(1),
            "warn" => Some(2),
            "info" => Some(3),
            "debug" => Some(4),
            "trace" => Some(5),
            _ => None,
        };
        if let Some(p) = parsed {
            level = p;
        }
    }
    MAX_LEVEL.store(level, Ordering::SeqCst);
    COLORS.store(if std::io::stderr().is_terminal() { 1 } else { 0 }, Ordering::SeqCst);
}

pub fn enabled(level: Level) -> bool {
    (level as u8) <= MAX_LEVEL.load(Ordering::SeqCst)
}

pub fn timestamp() -> String {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = now.as_secs();
    let millis = now.subsec_millis();
    let days = secs / 86400;
    let rem = secs % 86400;
    let (y, m, d) = civil_from_days(days as i64);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z",
        y,
        m,
        d,
        rem / 3600,
        (rem % 3600) / 60,
        rem % 60,
        millis
    )
}

// Howard Hinnant's algorithm
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn log(level: Level, target: &str, msg: &str) {
    if !enabled(level) {
        return;
    }
    let name = match level {
        Level::Error => "ERROR",
        Level::Warn => "WARN",
        Level::Info => "INFO",
        Level::Debug => "DEBUG",
        Level::Trace => "TRACE",
    };
    let level_str = if COLORS.load(Ordering::SeqCst) == 1 {
        let code = match level {
            Level::Error => Some("31"),
            Level::Warn => Some("33"),
            Level::Info => Some("36"),
            Level::Debug => Some("35"),
            Level::Trace => None,
        };
        match code {
            Some(c) => format!("\x1b[{}m{:<5}\x1b[0m", c, name),
            None => format!("{:<5}", name),
        }
    } else {
        format!("{:<5}", name)
    };
    let line = format!("{} {} [{}] {}\n", timestamp(), level_str, target, msg);
    let _g = LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let stderr = std::io::stderr();
    let mut h = stderr.lock();
    let _ = h.write_all(line.as_bytes());
    let _ = h.flush();
}

#[macro_export]
macro_rules! log_error {
    ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Error, $target, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_warn {
    ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Warn, $target, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_info {
    ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Info, $target, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_debug {
    ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Debug, $target, &format!($($arg)*)) };
}
#[macro_export]
macro_rules! log_trace {
    ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Trace, $target, &format!($($arg)*)) };
}
