//! Misc helpers: randomness, uuid, home dir, temp dir.

use std::fs::File;
use std::io::Read;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

static SEED: AtomicU64 = AtomicU64::new(0);

fn fill_random(buf: &mut [u8]) {
    if let Ok(mut f) = File::open("/dev/urandom") {
        if f.read_exact(buf).is_ok() {
            return;
        }
    }
    // fallback: xorshift seeded by time
    let mut s = SEED.load(Ordering::Relaxed);
    if s == 0 {
        s = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9e3779b97f4a7c15)
            | 1;
    }
    for b in buf.iter_mut() {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        *b = (s >> 24) as u8;
    }
    SEED.store(s, Ordering::Relaxed);
}

pub fn uuid_v4() -> String {
    let mut b = [0u8; 16];
    fill_random(&mut b);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    let hex: Vec<String> = b.iter().map(|x| format!("{:02x}", x)).collect();
    let h = hex.concat();
    format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32])
}

pub fn random_alnum(n: usize) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut buf = vec![0u8; n];
    fill_random(&mut buf);
    buf.iter().map(|b| CHARS[(*b as usize) % CHARS.len()] as char).collect()
}

/// Create a unique temporary directory like the `tempfile` crate (`.tmpXXXXXX` in the temp dir).
pub fn make_temp_dir() -> std::io::Result<PathBuf> {
    let base = std::env::temp_dir();
    let mut last_err = None;
    for _ in 0..1 << 20 {
        let p = base.join(format!(".tmp{}", random_alnum(6)));
        match std::fs::create_dir(&p) {
            Ok(()) => return Ok(p),
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                last_err = Some(e);
                continue;
            }
            Err(e) => return Err(e),
        }
    }
    Err(last_err.unwrap_or_else(|| std::io::Error::new(std::io::ErrorKind::Other, "too many temporary directories")))
}

extern "C" {
    fn getuid() -> u32;
    fn getpwuid_r(uid: u32, pwd: *mut Passwd, buf: *mut u8, buflen: usize, result: *mut *mut Passwd) -> i32;
}

#[repr(C)]
struct Passwd {
    pw_name: *mut u8,
    pw_passwd: *mut u8,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *mut u8,
    pw_dir: *mut u8,
    pw_shell: *mut u8,
}

fn passwd_home() -> Option<PathBuf> {
    unsafe {
        let mut buf = vec![0u8; 16384];
        let mut pw: Passwd = std::mem::zeroed();
        let mut result: *mut Passwd = std::ptr::null_mut();
        let r = getpwuid_r(getuid(), &mut pw, buf.as_mut_ptr(), buf.len(), &mut result);
        if r != 0 || result.is_null() || pw.pw_dir.is_null() {
            return None;
        }
        let cstr = std::ffi::CStr::from_ptr(pw.pw_dir as *const std::ffi::c_char);
        let s = cstr.to_string_lossy().into_owned();
        if s.is_empty() {
            return None;
        }
        Some(PathBuf::from(s))
    }
}

/// Home directory: `$HOME` if set (even if empty), otherwise from passwd.
pub fn home_dir() -> Option<PathBuf> {
    match std::env::var_os("HOME") {
        Some(h) => Some(PathBuf::from(h)),
        None => passwd_home(),
    }
}

pub fn host_triple() -> &'static str {
    if cfg!(all(target_arch = "x86_64", target_os = "linux", target_env = "gnu")) {
        "x86_64-unknown-linux-gnu"
    } else if cfg!(all(target_arch = "aarch64", target_os = "linux", target_env = "gnu")) {
        "aarch64-unknown-linux-gnu"
    } else if cfg!(all(target_arch = "x86_64", target_os = "linux", target_env = "musl")) {
        "x86_64-unknown-linux-musl"
    } else if cfg!(all(target_arch = "aarch64", target_os = "linux", target_env = "musl")) {
        "aarch64-unknown-linux-musl"
    } else if cfg!(all(target_arch = "x86_64", target_os = "macos")) {
        "x86_64-apple-darwin"
    } else if cfg!(all(target_arch = "aarch64", target_os = "macos")) {
        "aarch64-apple-darwin"
    } else if cfg!(all(target_arch = "x86_64", target_os = "windows")) {
        "x86_64-pc-windows-msvc"
    } else {
        "x86_64-unknown-linux-gnu"
    }
}
EOF
