//! Command line parsing emulating the clap-based interface of RustOwl.

use std::process::exit;

pub const VERSION: &str = "1.0.0-rc.1";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    PowerShell,
    Zsh,
    Nushell,
}

pub const SHELL_NAMES: [&str; 6] = ["bash", "elvish", "fish", "powershell", "zsh", "nushell"];

#[derive(Debug, Clone)]
pub enum Command {
    Check { path: Option<String>, all_targets: bool, all_features: bool },
    Clean,
    Toolchain(Option<ToolchainCommand>),
    Completions(Shell),
}

#[derive(Debug, Clone)]
pub enum ToolchainCommand {
    Install { path: Option<String>, skip_rustowl_toolchain: bool },
    Uninstall,
}

#[derive(Debug, Clone, Default)]
pub struct Opts {
    pub version: bool,
    pub quiet: u8,
    pub stdio: bool,
    pub command: Option<Command>,
}

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .map(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| "rustowl".to_string())
}

// ---------------------------------------------------------------------------
// Help texts
// ---------------------------------------------------------------------------

const ROOT_HELP: &str = "Usage: {bin} [OPTIONS] [COMMAND]

Commands:
