";

const UNINSTALL_HELP: &str = "Uninstall the toolchain

Usage: {bin} toolchain uninstall

Options:
  -h, --help  Print help
";

const COMPLETIONS_SHORT_HELP: &str = "Generate shell completions

Usage: {bin} completions <SHELL>

Arguments:
  <SHELL>  The shell to generate completions for [possible values: bash, elvish, fish, powershell, zsh, nushell]

Options:
  -h, --help  Print help (see more with '--help')
";

const COMPLETIONS_LONG_HELP: &str = "Generate shell completions

Usage: {bin} completions <SHELL>

Arguments:
  <SHELL>
          The shell to generate completions for

          Possible values:
          - bash:       Bourne Again `SHell` (bash)
          - elvish:     Elvish shell
          - fish:       Friendly Interactive `SHell` (fish)
          - powershell: `PowerShell`
          - zsh:        Z `SHell` (zsh)
          - nushell:    Nushell

Options:
  -h, --help
          Print help (see a summary with '-h')
";

const HELP_HELP: &str = "Print this message or the help of the given subcommand(s)

Usage: {bin} help [COMMAND]...

Arguments:
  [COMMAND]...  Print help for the subcommand(s)
";

const TOOLCHAIN_HELP_HELP: &str = "Print this message or the help of the given subcommand(s)

Usage: {bin} toolchain help [COMMAND]...

Arguments:
  [COMMAND]...  Print help for the subcommand(s)
";

// ---------------------------------------------------------------------------
// Command descriptions
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Cmd {
    Root,
    Check,
    Clean,
    Toolchain,
    Install,
    Uninstall,
    Completions,
    Help,
    ToolchainHelp,
}

struct FlagSpec {
    long: &'static str,
    short: Option<char>,
    takes_value: bool,
    /// clap's rendering in usage / error messages
    render: &'static str,
    count: bool,
}

const ROOT_FLAGS: &[FlagSpec] = &[
    FlagSpec { long: "version", short: Some('V'), takes_value: false, render: "--version", count: false },
    FlagSpec { long: "quiet", short: Some('q'), takes_value: false, render: "--quiet...", count: true },
    FlagSpec { long: "stdio", short: None, takes_value: false, render: "--stdio", count: false },
    FlagSpec { long: "help", short: Some('h'), takes_value: false, render: "--help", count: false },
];
const CHECK_FLAGS: &[FlagSpec] = &[
    FlagSpec { long: "all-targets", short: None, takes_value: false, render: "--all-targets", count: false },
    FlagSpec { long: "all-features", short: None, takes_value: false, render: "--all-features", count: false },
    FlagSpec { long: "help", short: Some('h'), takes_value: false, render: "--help", count: false },
];
const HELP_ONLY_FLAGS: &[FlagSpec] =
    &[FlagSpec { long: "help", short: Some('h'), takes_value: false, render: "--help", count: false }];
const INSTALL_FLAGS: &[FlagSpec] = &[
    FlagSpec { long: "path", short: None, takes_value: true, render: "--path <path>", count: false },
    FlagSpec { long: "skip-rustowl-toolchain", short: None, takes_value: false, render: "--skip-rustowl-toolchain", count: false },
    FlagSpec { long: "help", short: Some('h'), takes_value: false, render: "--help", count: false },
];

impl Cmd {
    fn flags(self) -> &'static [FlagSpec] {
        match self {
            Cmd::Root => ROOT_FLAGS,
            Cmd::Check => CHECK_FLAGS,
            Cmd::Clean | Cmd::Toolchain | Cmd::Uninstall | Cmd::Completions => HELP_ONLY_FLAGS,
            Cmd::Install => INSTALL_FLAGS,
            Cmd::Help | Cmd::ToolchainHelp => &[],
        }
    }
    fn subcommands(self) -> &'static [&'static str] {
        match self {
            Cmd::Root => &["check", "clean", "toolchain", "completions", "help"],
            Cmd::Toolchain => &["install", "uninstall", "help"],
            _ => &[],
        }
    }
    fn subcommand(self, name: &str) -> Option<Cmd> {
        match (self, name) {
            (Cmd::Root, "check") => Some(Cmd::Check),
            (Cmd::Root, "clean") => Some(Cmd::Clean),
            (Cmd::Root, "toolchain") => Some(Cmd::Toolchain),
            (Cmd::Root, "completions") => Some(Cmd::Completions),
            (Cmd::Root, "help") => Some(Cmd::Help),
            (Cmd::Toolchain, "install") => Some(Cmd::Install),
            (Cmd::Toolchain, "uninstall") => Some(Cmd::Uninstall),
            (Cmd::Toolchain, "help") => Some(Cmd::ToolchainHelp),
            _ => None,
        }
    }
    /// usage string without the leading bin name
    fn usage(self) -> &'static str {
        match self {
            Cmd::Root => "[OPTIONS] [COMMAND]",
            Cmd::Check => "check [OPTIONS] [path]",
            Cmd::Clean => "clean",
            Cmd::Toolchain => "toolchain [COMMAND]",
            Cmd::Install => "toolchain install [OPTIONS]",
            Cmd::Uninstall => "toolchain uninstall",
            Cmd::Completions => "completions <SHELL>",
            Cmd::Help => "help [COMMAND]...",
            Cmd::ToolchainHelp => "toolchain help [COMMAND]...",
        }
    }
    /// subcommand path prefix (e.g. "toolchain install")
    fn path(self) -> &'static str {
        match self {
            Cmd::Root => "",
            Cmd::Check => "check",
            Cmd::Clean => "clean",
            Cmd::Toolchain => "toolchain",
            Cmd::Install => "toolchain install",
            Cmd::Uninstall => "toolchain uninstall",
            Cmd::Completions => "completions",
            Cmd::Help => "help",
            Cmd::ToolchainHelp => "toolchain help",
        }
    }
    /// positional arguments rendering for "smart" usage lines
    fn positional_usage(self) -> &'static str {
        match self {
            Cmd::Check => " [path]",
            Cmd::Completions => " <SHELL>",
            _ => "",
        }
    }
    fn has_positional(self) -> bool {
        matches!(self, Cmd::Check | Cmd::Completions)
    }
    fn has_help_flag(self) -> bool {
        !matches!(self, Cmd::Help | Cmd::ToolchainHelp)
    }
    fn help_text(self, long: bool) -> &'static str {
        match self {
            Cmd::Root => ROOT_HELP,
            Cmd::Check => CHECK_HELP,
            Cmd::Clean => CLEAN_HELP,
            Cmd::Toolchain => TOOLCHAIN_HELP,
            Cmd::Install => INSTALL_HELP,
            Cmd::Uninstall => UNINSTALL_HELP,
            Cmd::Completions => {
                if long {
                    COMPLETIONS_LONG_HELP
                } else {
                    COMPLETIONS_SHORT_HELP
                }
            }
            Cmd::Help => HELP_HELP,
            Cmd::ToolchainHelp => TOOLCHAIN_HELP_HELP,
        }
    }
}

// ---------------------------------------------------------------------------
// Similarity (strsim::jaro) and did_you_mean
// ---------------------------------------------------------------------------

pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;
    for (i, a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len, i + search_range + 1);
        for (j, b_elem) in b.iter().enumerate().take(max_bound) {
            if min_bound <= j && a_elem == b_elem && !b_flags[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    let mut transpositions = 0usize;
    if matches != 0 {
        let mut b_iter = b_flags.iter().zip(b.iter());
        for (a_flag, ch1) in a_flags.iter().zip(a.iter()) {
            if *a_flag {
                loop {
                    if let Some((b_flag, ch2)) = b_iter.next() {
                        if !*b_flag {
                            continue;
                        }
                        if ch1 != ch2 {
                            transpositions += 1;
                        }
                        break;
                    } else {
                        break;
                    }
                }
            }
        }
    }
    transpositions /= 2;
    if matches == 0 {
        0.0
    } else {
        ((matches as f64 / a_len as f64)
            + (matches as f64 / b_len as f64)
            + ((matches - transpositions) as f64 / matches as f64))
            / 3.0
    }
}

/// Candidates sorted by ascending confidence (clap's `did_you_mean`).
fn did_you_mean<'a>(v: &str, candidates: impl IntoIterator<Item = &'a str>) -> Vec<String> {
    let mut c: Vec<(f64, String)> =
        candidates.into_iter().map(|pv| (jaro(v, pv), pv.to_string())).filter(|(conf, _)| *conf > 0.7).collect();
    c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    c.into_iter().map(|(_, s)| s).collect()
}

// ---------------------------------------------------------------------------
// Error reporting
// ---------------------------------------------------------------------------

struct CliError {
    msg: String,
    tip: Option<String>,
    usage: Option<String>,
    more_info: bool,
}

fn fail(e: CliError) -> ! {
    let mut out = format!("error: {}\n", e.msg);
    if let Some(t) = &e.tip {
        out.push_str(&format!("\n  tip: {}\n", t));
    }
    if let Some(u) = &e.usage {
        out.push_str(&format!("\nUsage: {}\n", u));
    }
    if e.more_info {
        out.push_str("\nFor more information, try '--help'.\n");
    }
    eprint!("{}", out);
    exit(2);
}

fn print_help(cmd: Cmd, long: bool) -> ! {
    let text = cmd.help_text(long).replace("{bin}", &bin_name());
    print!("{}", text);
    exit(0);
}

fn full_usage(cmd: Cmd) -> String {
    format!("{} {}", bin_name(), cmd.usage())
}

fn smart_usage(cmd: Cmd, flag_render: &str) -> String {
    let bin = bin_name();
    let path = cmd.path();
    if path.is_empty() {
        format!("{} {}{}", bin, flag_render, cmd.positional_usage())
    } else {
        format!("{} {} {}{}", bin, path, flag_render, cmd.positional_usage())
    }
}

fn unexpected_argument(cmd: Cmd, arg: &str, remaining: &[String], after_dd: bool) -> ! {
    let mut tip = None;
    let mut usage = full_usage(cmd);
    if after_dd {
        if cmd.subcommands().contains(&arg) {
            tip = Some(format!("subcommand '{}' exists; to use it, remove the '--' before it", arg));
        }
    } else if arg.starts_with("--") && arg.len() > 2 {
        let name = &arg[2..];
        let longs: Vec<&str> = cmd.flags().iter().map(|f| f.long).collect();
        let name_only = name.split('=').next().unwrap_or(name);
        let mut cands = did_you_mean(name_only, longs.iter().copied());
        if let Some(best) = cands.pop() {
            tip = Some(format!("a similar argument exists: '--{}'", best));
            if let Some(f) = cmd.flags().iter().find(|f| f.long == best) {
                usage = smart_usage(cmd, f.render);
            }
        } else {
            // check subcommands whose name appears in the remaining args
            let mut best: Option<(usize, String, String)> = None;
            for sub in cmd.subcommands() {
                if let Some(subcmd) = cmd.subcommand(sub) {
                    let longs: Vec<&str> = subcmd.flags().iter().map(|f| f.long).collect();
                    let mut c = did_you_mean(name_only, longs.iter().copied());
                    if let Some(cand) = c.pop() {
                        if let Some(pos) = remaining.iter().position(|x| x == sub) {
                            if best.as_ref().map(|b| pos < b.0).unwrap_or(true) {
                                best = Some((pos, sub.to_string(), cand));
                            }
                        }
                    }
                }
            }
            if let Some((_, sub, cand)) = best {
                tip = Some(format!("'{} --{}' exists", sub, cand));
            } else if cmd.has_positional() {
                tip = Some(format!("to pass '{}' as a value, use '-- {}'", arg, arg));
            }
        }
    } else if arg.starts_with('-') && arg.len() > 1 && cmd.has_positional() {
        tip = Some(format!("to pass '{}' as a value, use '-- {}'", arg, arg));
    }
    fail(CliError {
        msg: format!("unexpected argument '{}' found", arg),
        tip,
        usage: Some(usage),
        more_info: true,
    })
}

fn unrecognized_subcommand(cmd: Cmd, name: &str) -> ! {
    let cands = did_you_mean(name, cmd.subcommands().iter().copied());
    let tip = if cands.is_empty() {
        None
    } else if cands.len() == 1 {
        Some(format!("a similar subcommand exists: '{}'", cands[0]))
    } else {
        let list: Vec<String> = cands.iter().map(|c| format!("'{}'", c)).collect();
        Some(format!("some similar subcommands exist: {}", list.join(", ")))
    };
    fail(CliError {
        msg: format!("unrecognized subcommand '{}'", name),
        tip,
        usage: Some(full_usage(cmd)),
        more_info: cmd.has_help_flag(),
    })
}

fn value_required(render: &str, possible: bool) -> ! {
    let mut msg = format!("a value is required for '{}' but none was supplied", render);
    if possible {
        msg.push_str(&format!("\n  [possible values: {}]", SHELL_NAMES.join(", ")));
    }
    fail(CliError { msg, tip: None, usage: None, more_info: true })
}

fn parse_shell(v: &str) -> Shell {
    match v {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        "nushell" => Shell::Nushell,
        _ => {
            if v.is_empty() {
                value_required("<SHELL>", true);
            }
            let mut cands = did_you_mean(v, SHELL_NAMES.iter().copied());
            let tip = cands.pop().map(|c| format!("a similar value exists: '{}'", c));
            fail(CliError {
                msg: format!(
                    "invalid value '{}' for '<SHELL>'\n  [possible values: {}]",
                    v,
                    SHELL_NAMES.join(", ")
                ),
                tip,
                usage: None,
                more_info: true,
            })
        }
    }
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

struct ParseState {
    seen: Vec<&'static str>,
    counts: Vec<(&'static str, u32)>,
    values: Vec<(&'static str, String)>,
    positionals: Vec<String>,
}

impl ParseState {
    fn new() -> Self {
        ParseState { seen: vec![], counts: vec![], values: vec![], positionals: vec![] }
    }
    fn count(&self, name: &str) -> u32 {
        self.counts.iter().find(|(n, _)| *n == name).map(|(_, c)| *c).unwrap_or(0)
    }
    fn has(&self, name: &str) -> bool {
        self.seen.contains(&name)
    }
    fn value(&self, name: &str) -> Option<String> {
        self.values.iter().find(|(n, _)| *n == name).map(|(_, v)| v.clone())
    }
}

fn find_flag_long(cmd: Cmd, name: &str) -> Option<&'static FlagSpec> {
    cmd.flags().iter().find(|f| f.long == name)
}
fn find_flag_short(cmd: Cmd, c: char) -> Option<&'static FlagSpec> {
    cmd.flags().iter().find(|f| f.short == Some(c))
}

fn record_flag(cmd: Cmd, st: &mut ParseState, f: &'static FlagSpec) {
    if f.long == "help" {
        print_help(cmd, false);
    }
    if f.count {
        if let Some(e) = st.counts.iter_mut().find(|(n, _)| *n == f.long) {
            e.1 += 1;
        } else {
            st.counts.push((f.long, 1));
        }
        return;
    }
    if st.has(f.long) {
        fail(CliError {
            msg: format!("the argument '{}' cannot be used multiple times", f.render),
            tip: None,
            usage: Some(full_usage(cmd)),
            more_info: true,
        });
    }
    st.seen.push(f.long);
}

/// Parse the arguments of `cmd`. Returns the parse state and, if a subcommand
/// was encountered, the subcommand with its remaining args.
fn parse_cmd(cmd: Cmd, args: &[String]) -> (ParseState, Option<(Cmd, Vec<String>)>) {
    let mut st = ParseState::new();
    let mut i = 0;
    let mut after_dd = false;
    while i < args.len() {
        let arg = &args[i];
        i += 1;
        if after_dd {
            handle_positional(cmd, &mut st, arg, true);
            continue;
        }
        if arg == "--" {
            after_dd = true;
            continue;
        }
        if let Some(rest) = arg.strip_prefix("--") {
            let (name, inline_val) = match rest.find('=') {
                Some(p) => (&rest[..p], Some(rest[p + 1..].to_string())),
                None => (rest, None),
            };
            match find_flag_long(cmd, name) {
                Some(f) => {
                    if f.long == "help" {
                        print_help(cmd, true);
                    }
                    if f.takes_value {
                        if st.has(f.long) {
                            fail(CliError {
                                msg: format!("the argument '{}' cannot be used multiple times", f.render),
                                tip: None,
                                usage: Some(full_usage(cmd)),
                                more_info: true,
                            });
                        }
                        let val = match inline_val {
                            Some(v) => v,
                            None => {
                                if i < args.len() {
                                    let next = &args[i];
                                    if next.starts_with('-') && next.len() > 1 && next != "--" {
                                        // looks like a flag
                                        if next.starts_with("--") {
                                            let nn = next[2..].split('=').next().unwrap_or("");
                                            if find_flag_long(cmd, nn).is_some() {
                                                value_required(f.render, false);
                                            }
                                        } else if next.chars().nth(1).and_then(|c| find_flag_short(cmd, c)).is_some() {
                                            value_required(f.render, false);
                                        }
                                        let remaining: Vec<String> = args[i + 1..].to_vec();
                                        unexpected_argument(cmd, next, &remaining, false);
                                    }
                                    i += 1;
                                    next.clone()
                                } else {
                                    value_required(f.render, false);
                                }
                            }
                        };
                        if val.is_empty() {
                            value_required(f.render, false);
                        }
                        st.seen.push(f.long);
                        st.values.push((f.long, val));
                    } else {
                        if let Some(v) = inline_val {
                            fail(CliError {
                                msg: format!(
                                    "unexpected value '{}' for '{}' found; no more were expected",
                                    v, f.render
                                ),
                                tip: None,
                                usage: Some(smart_usage(cmd, f.render)),
                                more_info: true,
                            });
                        }
                        record_flag(cmd, &mut st, f);
                    }
                }
                None => {
                    let remaining: Vec<String> = args[i..].to_vec();
                    unexpected_argument(cmd, arg, &remaining, false);
                }
            }
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 {
            // short cluster
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                k += 1;
                match find_flag_short(cmd, c) {
                    Some(f) => {
                        if f.takes_value {
                            // not used by this CLI
                            let val: String = chars[k..].iter().collect();
                            if val.is_empty() {
                                value_required(f.render, false);
                            }
                            st.seen.push(f.long);
                            st.values.push((f.long, val));
                            k = chars.len();
                        } else {
                            if chars.get(k) == Some(&'=') {
                                let remaining: Vec<String> = args[i..].to_vec();
                                unexpected_argument(cmd, "-=", &remaining, false);
                            }
                            record_flag(cmd, &mut st, f);
                        }
                    }
                    None => {
                        let remaining: Vec<String> = args[i..].to_vec();
                        unexpected_argument(cmd, &format!("-{}", c), &remaining, false);
                    }
                }
            }
            continue;
        }
        // positional / subcommand
        if !cmd.subcommands().is_empty() {
            match cmd.subcommand(arg) {
                Some(sub) => {
                    return (st, Some((sub, args[i..].to_vec())));
                }
                None => unrecognized_subcommand(cmd, arg),
            }
        }
        handle_positional(cmd, &mut st, arg, false);
    }
    (st, None)
}

fn handle_positional(cmd: Cmd, st: &mut ParseState, arg: &str, after_dd: bool) {
    match cmd {
        Cmd::Check => {
            if st.positionals.is_empty() {
                if arg.is_empty() {
                    value_required("[path]", false);
                }
                st.positionals.push(arg.to_string());
            } else {
                unexpected_argument(cmd, arg, &[], after_dd);
            }
        }
        Cmd::Completions => {
            if st.positionals.is_empty() {
                st.positionals.push(arg.to_string());
            } else {
                unexpected_argument(cmd, arg, &[], after_dd);
            }
        }
        _ => unexpected_argument(cmd, arg, &[], after_dd),
    }
}

/// Handle `help [COMMAND]...` starting from `base`.
fn run_help(base: Cmd, words: &[String]) -> ! {
    let mut cur = base;
    for w in words {
        match cur.subcommand(w) {
            Some(sub) => cur = sub,
            None => unrecognized_subcommand(cur, w),
        }
    }
    print_help(cur, true);
}

pub fn parse() -> Opts {
    let args: Vec<String> = std::env::args_os().skip(1).map(|a| a.to_string_lossy().into_owned()).collect();
    let mut opts = Opts::default();
    let (root_st, sub) = parse_cmd(Cmd::Root, &args);
    opts.version = root_st.has("version");
    opts.quiet = root_st.count("quiet").min(255) as u8;
    opts.stdio = root_st.has("stdio");
    let (sub, rest) = match sub {
        None => return opts,
        Some(s) => s,
    };
    match sub {
        Cmd::Help => run_help(Cmd::Root, &rest),
        Cmd::Check => {
            let (st, _) = parse_cmd(Cmd::Check, &rest);
            opts.command = Some(Command::Check {
                path: st.positionals.first().cloned(),
                all_targets: st.has("all-targets"),
                all_features: st.has("all-features"),
            });
        }
        Cmd::Clean => {
            parse_cmd(Cmd::Clean, &rest);
            opts.command = Some(Command::Clean);
        }
        Cmd::Completions => {
            let (st, _) = parse_cmd(Cmd::Completions, &rest);
            let shell = match st.positionals.first() {
                Some(v) => parse_shell(v),
                None => fail(CliError {
                    msg: "the following required arguments were not provided:\n  <SHELL>".to_string(),
                    tip: None,
                    usage: Some(full_usage(Cmd::Completions)),
                    more_info: true,
                }),
            };
            opts.command = Some(Command::Completions(shell));
        }
        Cmd::Toolchain => {
            let (_, tsub) = parse_cmd(Cmd::Toolchain, &rest);
            match tsub {
                None => opts.command = Some(Command::Toolchain(None)),
                Some((Cmd::ToolchainHelp, words)) => run_help(Cmd::Toolchain, &words),
                Some((Cmd::Install, r)) => {
                    let (st, _) = parse_cmd(Cmd::Install, &r);
                    opts.command = Some(Command::Toolchain(Some(ToolchainCommand::Install {
                        path: st.value("path"),
                        skip_rustowl_toolchain: st.has("skip-rustowl-toolchain"),
                    })));
                }
                Some((Cmd::Uninstall, r)) => {
                    parse_cmd(Cmd::Uninstall, &r);
                    opts.command = Some(Command::Toolchain(Some(ToolchainCommand::Uninstall)));
                }
                Some(_) => unreachable!(),
            }
        }
        _ => unreachable!(),
    }
    opts
}
EOF
echo ok"}

