// ---------------------------------------------------------------------------
// Installation
// ---------------------------------------------------------------------------

fn format_connect_error(url: &str, host: &str, port: u16) -> String {
    use std::net::ToSocketAddrs;
    let source = match (host, port).to_socket_addrs() {
        Err(e) => format!("ConnectError(\"dns error\", {:?})", e),
        Ok(mut addrs) => {
            let mut err = None;
            let mut ok = false;
            for a in addrs.by_ref() {
                match std::net::TcpStream::connect_timeout(&a, std::time::Duration::from_secs(10)) {
                    Ok(_) => {
                        ok = true;
                        break;
                    }
                    Err(e) => err = Some(e),
                }
            }
            if ok {
                "hyper::Error(Io, Custom { kind: Other, error: \"download failed\" })".to_string()
            } else {
                match err {
                    Some(e) => format!("ConnectError(\"tcp connect error\", {:?})", e),
                    None => "ConnectError(\"dns error\", Custom { kind: Uncategorized, error: \"failed to lookup address information: Name or service not known\" })".to_string(),
                }
            }
        }
    };
    if source.starts_with("ConnectError") {
        format!(
            "reqwest::Error {{ kind: Request, url: \"{}\", source: hyper_util::client::legacy::Error(Connect, {}) }}",
            url, source
        )
    } else {
        format!("reqwest::Error {{ kind: Request, url: \"{}\", source: {} }}", url, source)
    }
}

fn url_host(url: &str) -> (String, u16) {
    let rest = url.split("://").nth(1).unwrap_or(url);
    let hostport = rest.split('/').next().unwrap_or("");
    let secure = url.starts_with("https");
    match hostport.rsplit_once(':') {
        Some((h, p)) if p.chars().all(|c| c.is_ascii_digit()) && !p.is_empty() => {
            (h.to_string(), p.parse().unwrap_or(if secure { 443 } else { 80 }))
        }
        _ => (hostport.to_string(), if secure { 443 } else { 80 }),
    }
}

fn url_origin(url: &str) -> String {
    let scheme = url.split("://").next().unwrap_or("https");
    let (host, _) = url_host(url);
    format!("{}://{}/", scheme, host)
}

/// Download `url` into `dest`. Returns a reqwest-like error description on failure.
fn download(url: &str, dest: &Path) -> Result<(), String> {
    log_info!(TARGET, "start downloading {}...", url);
    log_debug!("reqwest::connect", "starting new connection: {}", url_origin(url));
    let (host, port) = url_host(url);
    // Probe connectivity first so that failures are reported the same way reqwest does.
    use std::net::ToSocketAddrs;
    let addrs = match (host.as_str(), port).to_socket_addrs() {
        Ok(a) => a.collect::<Vec<_>>(),
        Err(_) => {
            log_trace!("reqwest::retry", "shouldn't retry!");
            return Err(format_connect_error(url, &host, port));
        }
    };
    let mut connected = false;
    for a in &addrs {
        if std::net::TcpStream::connect_timeout(a, std::time::Duration::from_secs(10)).is_ok() {
            connected = true;
            break;
        }
    }
    if !connected {
        log_trace!("reqwest::retry", "shouldn't retry!");
        return Err(format_connect_error(url, &host, port));
    }
    let status = Command::new("curl")
        .args(["-fsSL", "--retry", "2", "-o"])
        .arg(dest)
        .arg(url)
        .status();
    match status {
        Ok(s) if s.success() => Ok(()),
        Ok(s) => Err(format!(
            "reqwest::Error {{ kind: Status({}), url: \"{}\" }}",
            s.code().map(|c| if c == 22 { 404 } else { c }).unwrap_or(0),
