fn extract_tarball(tarball: &Path, dest: &Path) -> Result<(), String> {
    std::fs::create_dir_all(dest).map_err(|e| format!("{:?}", e))?;
    let status = Command::new("tar")
        .arg("xzf")
        .arg(tarball)
        .arg("-C")
        .arg(dest)
        .status()
        .map_err(|e| format!("{:?}", e))?;
    if status.success() {
        Ok(())
    } else {
        Err(format!("tar exited with {}", status))
    }
}

fn install_rust_component(component: &str, tmp: &Path, sysroot: &Path) -> Result<(), ()> {
    let file_name = format!("{}-{}-{}.tar.gz", component, TOOLCHAIN_CHANNEL, host_tuple());
    let url = format!("{}/{}/{}", RUST_DIST_BASE, TOOLCHAIN_DATE, file_name);
    let tarball = tmp.join(&file_name);
    if let Err(e) = download(&url, &tarball) {
        log_error!(TARGET, "failed to download tarball");
        log_error!(TARGET, "{}", e);
        return Err(());
    }
    log_info!(TARGET, "extracting {}...", file_name);
    let extract_dir = tmp.join(format!("{}-extract", component));
    if let Err(e) = extract_tarball(&tarball, &extract_dir) {
        log_error!(TARGET, "failed to extract tarball");
        log_error!(TARGET, "{}", e);
        return Err(());
    }
    // the tarball contains a single directory with an install.sh
    let inner = std::fs::read_dir(&extract_dir)
        .ok()
        .and_then(|rd| rd.filter_map(|e| e.ok()).map(|e| e.path()).find(|p| p.is_dir()));
    let inner = match inner {
        Some(p) => p,
        None => {
