    };
    log_info!(TARGET, "installing {}...", component);
    let status = Command::new("sh")
        .arg(inner.join("install.sh"))
        .arg(format!("--prefix={}", sysroot.display()))
        .arg("--disable-ldconfig")
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
