        }
    }
}

fn install_rustowl_toolchain(tmp: &Path, sysroot: &Path) -> Result<(), ()> {
    log_info!(TARGET, "start installing RustOwl toolchain...");
    let file_name = format!("rustowl-{}.tar.gz", host_tuple());
    let url = format!("{}/v{}/{}", RUSTOWL_RELEASE_BASE, crate::cli::VERSION, file_name);
    let tarball = tmp.join(&file_name);
