            root = entries[0].clone();
        }
    }
    if let Err(e) = copy_tree(&root, sysroot) {
        log_error!(TARGET, "failed to install RustOwl toolchain: {:?}", e);
        return Err(());
    }
    Ok(())
}

/// Install the toolchain into `runtime_dir`.
pub fn install(runtime_dir: &Path, skip_rustowl_toolchain: bool) -> Result<(), ()> {
