//! `cargo metadata` invocation and parsing.

use crate::json::{self, Value};
use crate::toolchain;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

#[derive(Debug, Clone)]
pub struct Package {
    pub name: String,
    pub id: String,
}

#[derive(Debug, Clone)]
pub struct Metadata {
    pub packages: Vec<Package>,
    pub workspace_root: PathBuf,
    pub target_directory: PathBuf,
    pub root_package: Option<Package>,
}

fn parse_metadata(text: &str) -> Option<Metadata> {
    let v = json::parse(text).ok()?;
    let packages_v = v.get("packages")?.as_array()?;
    let mut packages = Vec::new();
    for p in packages_v {
        let name = p.get("name")?.as_str()?.to_string();
        let id = p.get("id")?.as_str()?.to_string();
        packages.push(Package { name, id });
    }
    let workspace_root = PathBuf::from(v.get("workspace_root")?.as_str()?);
    let target_directory = PathBuf::from(v.get("target_directory")?.as_str()?);
    // version must be present (cargo_metadata requires it)
    v.get("version")?;
    v.get("workspace_members")?.as_array()?;
    let root_package = match v.get("resolve") {
        Some(Value::Object(r)) => match r.get("root") {
            Some(Value::String(root_id)) => packages.iter().find(|p| &p.id == root_id).cloned(),
            _ => None,
        },
        _ => None,
    };
    Some(Metadata { packages, workspace_root, target_directory, root_package })
}

fn run_metadata(mut cmd: Command, cwd: &Path) -> Option<Metadata> {
    cmd.current_dir(cwd).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::null());
    let output = cmd.output().ok()?;
    if !output.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&output.stdout);
    parse_metadata(&text)
}

/// `cargo metadata --filter-platform <host>` with the RustOwl toolchain environment.
pub fn metadata_with_toolchain(sysroot: &Path, cwd: &Path) -> Option<Metadata> {
    let mut cmd = toolchain::cargo_command(sysroot);
    cmd.arg("metadata").arg("--filter-platform").arg(toolchain::host_tuple());
    run_metadata(cmd, cwd)
}

/// Plain `cargo metadata --format-version 1` (used by `clean`).
pub fn metadata_plain(cwd: &Path) -> Option<Metadata> {
    let mut cmd = Command::new("cargo");
    cmd.arg("metadata").arg("--format-version").arg("1");
    run_metadata(cmd, cwd)
}
