//! Data model of the analysis result emitted by `rustowlc` and the
//! decoration computation used by the LSP `rustowl/cursor` request.

use crate::json::{Number, Value};
use std::collections::HashMap;
use std::path::PathBuf;

pub type Loc = u32;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub struct Range {
    pub from: Loc,
    pub until: Loc,
}

impl Range {
    pub fn new(from: Loc, until: Loc) -> Self {
        Range { from, until }
    }
    pub fn contains(&self, pos: Loc) -> bool {
        self.from <= pos && pos <= self.until
    }
    pub fn size(&self) -> i64 {
        self.until as i64 - self.from as i64
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub struct FnLocal {
    pub id: u32,
    pub fn_id: u32,
}

#[derive(Clone, Debug)]
pub enum MirDecl {
    User {
        local: FnLocal,
        name: String,
        span: Range,
        ty: String,
        lives: Vec<Range>,
        shared_borrow: Vec<Range>,
        mutable_borrow: Vec<Range>,
        drop: bool,
        drop_range: Vec<Range>,
        must_live_at: Vec<Range>,
    },
    Other {
        local: FnLocal,
        ty: String,
        lives: Vec<Range>,
        shared_borrow: Vec<Range>,
        mutable_borrow: Vec<Range>,
        drop: bool,
        drop_range: Vec<Range>,
        must_live_at: Vec<Range>,
    },
}

impl MirDecl {
    pub fn local(&self) -> FnLocal {
        match self {
            MirDecl::User { local, .. } | MirDecl::Other { local, .. } => *local,
        }
    }
    pub fn lives(&self) -> &Vec<Range> {
        match self {
            MirDecl::User { lives, .. } | MirDecl::Other { lives, .. } => lives,
        }
    }
    pub fn drop(&self) -> bool {
        match self {
            MirDecl::User { drop, .. } | MirDecl::Other { drop, .. } => *drop,
        }
    }
    pub fn drop_range(&self) -> &Vec<Range> {
        match self {
            MirDecl::User { drop_range, .. } | MirDecl::Other { drop_range, .. } => drop_range,
        }
    }
    pub fn must_live_at(&self) -> &Vec<Range> {
        match self {
            MirDecl::User { must_live_at, .. } | MirDecl::Other { must_live_at, .. } => must_live_at,
        }
    }
    pub fn name(&self) -> Option<&str> {
        match self {
            MirDecl::User { name, .. } => Some(name),
            MirDecl::Other { .. } => None,
        }
    }
}

#[derive(Clone, Debug)]
pub enum MirRval {
    Move { target_local: FnLocal, range: Range },
    Borrow { target_local: FnLocal, range: Range, mutable: bool, outlive: Option<Range> },
}

#[derive(Clone, Debug)]
pub enum MirStatement {
    StorageLive { target_local: FnLocal, range: Range },
    StorageDead { target_local: FnLocal, range: Range },
    Assign { target_local: FnLocal, range: Range, rval: Option<MirRval> },
    Other { range: Range },
}

#[derive(Clone, Debug)]
pub enum MirTerminator {
    Drop { local: FnLocal, range: Range },
    Call { destination_local: FnLocal, fn_span: Range },
    Other { range: Range },
}

#[derive(Clone, Debug)]
pub struct MirBasicBlock {
    pub statements: Vec<MirStatement>,
    pub terminator: Option<MirTerminator>,
}

#[derive(Clone, Debug)]
pub struct Function {
    pub fn_id: u32,
    pub basic_blocks: Vec<MirBasicBlock>,
    pub decls: Vec<MirDecl>,
}

#[derive(Clone, Debug, Default)]
pub struct File {
    pub items: Vec<Function>,
}

#[derive(Clone, Debug, Default)]
pub struct Crate(pub HashMap<PathBuf, File>);

#[derive(Clone, Debug, Default)]
pub struct Workspace(pub HashMap<String, Crate>);

impl Workspace {
    pub fn merge(&mut self, other: Workspace) {
        for (name, krate) in other.0 {
            let entry = self.0.entry(name).or_default();
            for (path, file) in krate.0 {
                entry.0.entry(path).or_default().items.extend(file.items);
            }
        }
    }
    pub fn file_count(&self) -> usize {
        self.0.values().map(|c| c.0.len()).sum()
    }
    /// Find the analysis of a file: the first crate containing the path wins.
    pub fn find_file(&self, path: &std::path::Path) -> Option<&File> {
        for krate in self.0.values() {
            for (p, f) in &krate.0 {
                if p.as_path() == path {
                    return Some(f);
                }
            }
        }
        None
    }
}

// ---------------------------------------------------------------------------
// Deserialization (serde-like strictness)
// ---------------------------------------------------------------------------

type DeResult<T> = Result<T, String>;

fn field<'a>(obj: &'a Value, name: &str) -> DeResult<&'a Value> {
    obj.get(name).ok_or_else(|| format!("missing field `{}`", name))
}

fn de_u32(v: &Value) -> DeResult<u32> {
    match v {
        Value::Number(Number::PosInt(n)) if *n <= u32::MAX as u64 => Ok(*n as u32),
        Value::Number(Number::PosInt(n)) => Err(format!("invalid value: integer `{}`, expected u32", n)),
        Value::Number(Number::NegInt(n)) => Err(format!("invalid value: integer `{}`, expected u32", n)),
        other => Err(format!("invalid type: {}, expected u32", other.unexpected())),
    }
}

fn de_bool(v: &Value) -> DeResult<bool> {
    match v {
        Value::Bool(b) => Ok(*b),
        other => Err(format!("invalid type: {}, expected a boolean", other.unexpected())),
    }
}

fn de_string(v: &Value) -> DeResult<String> {
    match v {
        Value::String(s) => Ok(s.clone()),
        other => Err(format!("invalid type: {}, expected a string", other.unexpected())),
    }
}

/// Access struct fields either from a map or (positionally) from a sequence.
struct StructView<'a> {
    obj: Option<&'a Value>,
    seq: Option<&'a Vec<Value>>,
}

fn struct_view<'a>(v: &'a Value, name: &str) -> DeResult<StructView<'a>> {
    match v {
        Value::Object(_) => Ok(StructView { obj: Some(v), seq: None }),
        Value::Array(a) => Ok(StructView { obj: None, seq: Some(a) }),
        other => Err(format!("invalid type: {}, expected struct {}", other.unexpected(), name)),
    }
}

impl<'a> StructView<'a> {
    fn get(&self, idx: usize, name: &str, total: usize, sname: &str) -> DeResult<&'a Value> {
        if let Some(o) = self.obj {
            field(o, name)
        } else {
            let seq = self.seq.unwrap();
            seq.get(idx).ok_or_else(|| {
                format!("invalid length {}, expected struct {} with {} elements", seq.len(), sname, total)
            })
        }
    }
    fn get_opt(&self, idx: usize, name: &str) -> Option<&'a Value> {
        if let Some(o) = self.obj {
            o.get(name)
        } else {
            self.seq.unwrap().get(idx)
        }
    }
}

pub fn de_range(v: &Value) -> DeResult<Range> {
    let sv = struct_view(v, "Range")?;
    let from = de_u32(sv.get(0, "from", 2, "Range")?)?;
    let until = de_u32(sv.get(1, "until", 2, "Range")?)?;
    Ok(Range { from, until })
}

fn de_opt_range(v: Option<&Value>) -> DeResult<Option<Range>> {
    match v {
        None | Some(Value::Null) => Ok(None),
        Some(x) => Ok(Some(de_range(x)?)),
    }
}

fn de_ranges(v: &Value) -> DeResult<Vec<Range>> {
    match v {
        Value::Array(a) => a.iter().map(de_range).collect(),
        other => Err(format!("invalid type: {}, expected a sequence", other.unexpected())),
    }
}

fn de_fn_local(v: &Value) -> DeResult<FnLocal> {
    let sv = struct_view(v, "FnLocal")?;
    let id = de_u32(sv.get(0, "id", 2, "FnLocal")?)?;
    let fn_id = de_u32(sv.get(1, "fn_id", 2, "FnLocal")?)?;
    Ok(FnLocal { id, fn_id })
}

fn tag<'a>(v: &'a Value, variants: &[&str]) -> DeResult<&'a str> {
    let obj = match v {
        Value::Object(_) => v,
        other => return Err(format!("invalid type: {}, expected internally tagged enum", other.unexpected())),
    };
    let t = obj.get("type").ok_or_else(|| "missing field `type`".to_string())?;
    let t = de_string(t)?;
    if variants.contains(&t.as_str()) {
        Ok(obj.get("type").unwrap().as_str().unwrap())
    } else {
        Err(format!("unknown variant `{}`, expected one of {}", t, variants.iter().map(|v| format!("`{}`", v)).collect::<Vec<_>>().join(", ")))
    }
}

fn de_decl(v: &Value) -> DeResult<MirDecl> {
    let t = tag(v, &["user", "other"])?;
    let local = de_fn_local(field(v, "local")?)?;
    match t {
        "user" => Ok(MirDecl::User {
            local,
            name: de_string(field(v, "name")?)?,
            span: de_range(field(v, "span")?)?,
            ty: de_string(field(v, "ty")?)?,
            lives: de_ranges(field(v, "lives")?)?,
            shared_borrow: de_ranges(field(v, "shared_borrow")?)?,
            mutable_borrow: de_ranges(field(v, "mutable_borrow")?)?,
            drop: de_bool(field(v, "drop")?)?,
            drop_range: de_ranges(field(v, "drop_range")?)?,
            must_live_at: de_ranges(field(v, "must_live_at")?)?,
        }),
        _ => Ok(MirDecl::Other {
            local,
            ty: de_string(field(v, "ty")?)?,
            lives: de_ranges(field(v, "lives")?)?,
            shared_borrow: de_ranges(field(v, "shared_borrow")?)?,
            mutable_borrow: de_ranges(field(v, "mutable_borrow")?)?,
            drop: de_bool(field(v, "drop")?)?,
            drop_range: de_ranges(field(v, "drop_range")?)?,
            must_live_at: de_ranges(field(v, "must_live_at")?)?,
        }),
    }
}

fn de_rval(v: &Value) -> DeResult<MirRval> {
    let t = tag(v, &["move", "borrow"])?;
    let target_local = de_fn_local(field(v, "target_local")?)?;
    let range = de_range(field(v, "range")?)?;
    match t {
        "move" => Ok(MirRval::Move { target_local, range }),
        _ => Ok(MirRval::Borrow {
            target_local,
            range,
            mutable: de_bool(field(v, "mutable")?)?,
            outlive: de_opt_range(v.get("outlive"))?,
        }),
    }
}

fn de_statement(v: &Value) -> DeResult<MirStatement> {
    let t = tag(v, &["storage_live", "storage_dead", "assign", "other"])?;
    match t {
        "storage_live" => Ok(MirStatement::StorageLive {
            target_local: de_fn_local(field(v, "target_local")?)?,
            range: de_range(field(v, "range")?)?,
        }),
        "storage_dead" => Ok(MirStatement::StorageDead {
            target_local: de_fn_local(field(v, "target_local")?)?,
            range: de_range(field(v, "range")?)?,
        }),
        "assign" => Ok(MirStatement::Assign {
            target_local: de_fn_local(field(v, "target_local")?)?,
            range: de_range(field(v, "range")?)?,
            rval: match v.get("rval") {
                None | Some(Value::Null) => None,
                Some(r) => Some(de_rval(r)?),
            },
        }),
        _ => Ok(MirStatement::Other { range: de_range(field(v, "range")?)? }),
    }
}

fn de_terminator(v: &Value) -> DeResult<MirTerminator> {
    let t = tag(v, &["drop", "call", "other"])?;
    match t {
        "drop" => Ok(MirTerminator::Drop {
            local: de_fn_local(field(v, "local")?)?,
            range: de_range(field(v, "range")?)?,
        }),
        "call" => Ok(MirTerminator::Call {
            destination_local: de_fn_local(field(v, "destination_local")?)?,
            fn_span: de_range(field(v, "fn_span")?)?,
        }),
        _ => Ok(MirTerminator::Other { range: de_range(field(v, "range")?)? }),
    }
}

fn de_basic_block(v: &Value) -> DeResult<MirBasicBlock> {
    let sv = struct_view(v, "MirBasicBlock")?;
    let statements = match sv.get(0, "statements", 2, "MirBasicBlock")? {
        Value::Array(a) => a.iter().map(de_statement).collect::<DeResult<Vec<_>>>()?,
        other => return Err(format!("invalid type: {}, expected a sequence", other.unexpected())),
    };
    let terminator = match sv.get_opt(1, "terminator") {
        None | Some(Value::Null) => None,
        Some(t) => Some(de_terminator(t)?),
    };
    Ok(MirBasicBlock { statements, terminator })
}

fn de_function(v: &Value) -> DeResult<Function> {
    let sv = struct_view(v, "Function")?;
    let fn_id = de_u32(sv.get(0, "fn_id", 3, "Function")?)?;
    let basic_blocks = match sv.get(1, "basic_blocks", 3, "Function")? {
        Value::Array(a) => a.iter().map(de_basic_block).collect::<DeResult<Vec<_>>>()?,
        other => return Err(format!("invalid type: {}, expected a sequence", other.unexpected())),
    };
    let decls = match sv.get(2, "decls", 3, "Function")? {
        Value::Array(a) => a.iter().map(de_decl).collect::<DeResult<Vec<_>>>()?,
        other => return Err(format!("invalid type: {}, expected a sequence", other.unexpected())),
    };
    Ok(Function { fn_id, basic_blocks, decls })
}

fn de_file(v: &Value) -> DeResult<File> {
    let sv = struct_view(v, "File")?;
    let items = match sv.get(0, "items", 1, "File")? {
        Value::Array(a) => a.iter().map(de_function).collect::<DeResult<Vec<_>>>()?,
        other => return Err(format!("invalid type: {}, expected a sequence", other.unexpected())),
    };
    Ok(File { items })
}

pub fn de_workspace(v: &Value) -> DeResult<Workspace> {
    let crates = match v {
        Value::Object(m) => m,
        other => return Err(format!("invalid type: {}, expected a map", other.unexpected())),
    };
    let mut ws = Workspace::default();
    for (name, cv) in crates {
        let files = match cv {
            Value::Object(m) => m,
            other => return Err(format!("invalid type: {}, expected a map", other.unexpected())),
        };
        let mut krate = Crate::default();
        for (path, fv) in files {
            krate.0.insert(PathBuf::from(path), de_file(fv)?);
        }
        ws.0.insert(name.clone(), krate);
    }
    Ok(ws)
}

/// Parse one line of `rustowlc` output.
pub fn parse_workspace_line(line: &str) -> Option<Workspace> {
    let v = crate::json::parse(line).ok()?;
    de_workspace(&v).ok()
}

// ---------------------------------------------------------------------------
// Decorations
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DecoKind {
    Lifetime,
    ImmBorrow,
    MutBorrow,
    Move,
    Call,
    Outlive,
}

impl DecoKind {
    pub fn name(self) -> &'static str {
        match self {
            DecoKind::Lifetime => "lifetime",
            DecoKind::ImmBorrow => "imm_borrow",
            DecoKind::MutBorrow => "mut_borrow",
            DecoKind::Move => "move",
            DecoKind::Call => "call",
            DecoKind::Outlive => "outlive",
        }
    }
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Decoration {
    pub kind: DecoKind,
    pub range: Range,
    pub hover_text: String,
    pub local: FnLocal,
    pub overlapped: bool,
}

/// Merge overlapping (or touching) ranges, keeping the position of the first
/// range of each merged group.
pub fn merge_ranges(ranges: &[Range]) -> Vec<Range> {
    let mut result: Vec<Range> = Vec::new();
    for r in ranges {
        result.push(*r);
    }
    let overlaps = |a: &Range, b: &Range| a.from <= b.until && b.from <= a.until;
    loop {
        let mut changed = false;
        'outer: for i in 0..result.len() {
            for j in (i + 1)..result.len() {
                if overlaps(&result[i], &result[j]) {
                    let merged = Range {
                        from: result[i].from.min(result[j].from),
                        until: result[i].until.max(result[j].until),
                    };
                    result[i] = merged;
                    result.remove(j);
                    changed = true;
                    break 'outer;
                }
            }
        }
        if !changed {
            break;
        }
    }
    result
}

/// Remove `b` from `a`, returning the (at most two) remaining parts.
fn subtract(a: Range, b: Range) -> Option<(Range, Vec<Range>)> {
    let from = a.from.max(b.from);
    let until = a.until.min(b.until);
    if from >= until {
        return None;
    }
    let mut rest = Vec::new();
    if b.from > 0 {
        let left = Range::new(a.from, b.from - 1);
        if left.from < left.until {
            rest.push(left);
        }
    }
    if b.until < u32::MAX {
        let right = Range::new(b.until + 1, a.until);
        if right.from < right.until {
            rest.push(right);
        }
    }
    Some((Range::new(from, until), rest))
}

/// `ranges` minus all of `excludes`.
pub fn eliminate_ranges(ranges: &[Range], excludes: &[Range]) -> Vec<Range> {
    fn go(r: Range, excludes: &[Range], out: &mut Vec<Range>) {
        for (i, e) in excludes.iter().enumerate() {
            if let Some((_, rest)) = subtract(r, *e) {
                for part in rest {
                    go(part, &excludes[i + 1..], out);
                }
                return;
            }
        }
        out.push(r);
    }
    let mut out = Vec::new();
    for r in ranges {
        go(*r, excludes, &mut out);
    }
    out
}

fn lifetime_ranges(decl: &MirDecl) -> Vec<Range> {
    if decl.drop() {
        merge_ranges(decl.drop_range())
    } else {
        merge_ranges(decl.lives())
    }
}

fn select_local(items: &[&Function], pos: Loc) -> Option<FnLocal> {
    // user variable declarations: smallest span wins
    let mut best: Option<(i64, FnLocal)> = None;
    for f in items {
        for d in &f.decls {
            if let MirDecl::User { local, span, .. } = d {
                if span.contains(pos) {
                    let s = span.size();
                    if best.map(|b| s < b.0).unwrap_or(true) {
                        best = Some((s, *local));
                    }
                }
            }
        }
    }
    if let Some((_, l)) = best {
        return Some(l);
    }
    // statements: smallest range wins
    let mut best: Option<(i64, FnLocal)> = None;
    for f in items {
        for bb in &f.basic_blocks {
            for st in &bb.statements {
                if let MirStatement::Assign { rval: Some(rv), .. } = st {
                    let (target, range) = match rv {
                        MirRval::Move { target_local, range } => (*target_local, *range),
                        MirRval::Borrow { target_local, range, .. } => (*target_local, *range),
                    };
                    if range.contains(pos) {
                        let s = range.size();
                        if best.map(|b| s < b.0).unwrap_or(true) {
                            best = Some((s, target));
                        }
                    }
                }
            }
        }
    }
    if let Some((_, l)) = best {
        return Some(l);
    }
    // terminators: largest range wins
    let mut best: Option<(i64, FnLocal)> = None;
    for f in items {
        for bb in &f.basic_blocks {
            if let Some(MirTerminator::Call { destination_local, fn_span }) = &bb.terminator {
                if fn_span.contains(pos) {
                    let s = fn_span.size();
                    if best.map(|b| s > b.0).unwrap_or(true) {
                        best = Some((s, *destination_local));
                    }
                }
            }
        }
    }
    best.map(|(_, l)| l)
}

fn lifetime_text(decl: &MirDecl) -> String {
    match decl.name() {
        Some(n) => format!("lifetime of variable `{}`", n),
        None => "lifetime of anonymous variable".to_string(),
    }
}

fn outlive_text(decl: &MirDecl) -> String {
    match decl.name() {
        Some(n) => format!("variable `{}` is required to live here", n),
        None => "anonymous variable is required to live here".to_string(),
    }
}

fn push_unique(v: &mut Vec<Decoration>, d: Decoration) {
    if !v.contains(&d) {
        v.push(d);
    }
}

/// Split `d` against later decorations, marking overlapping parts.
fn split_overlaps(d: &Decoration, later: &[Decoration], out: &mut Vec<Decoration>) {
    for (i, other) in later.iter().enumerate() {
        if let Some((common, rest)) = subtract(d.range, other.range) {
            out.push(Decoration { range: common, overlapped: true, ..d.clone() });
            for part in rest {
                let piece = Decoration { range: part, overlapped: false, ..d.clone() };
                split_overlaps(&piece, &later[i + 1..], out);
            }
            return;
        }
    }
    out.push(d.clone());
}

/// Compute decorations for the cursor position `pos` within the given file items.
pub fn compute_decorations(items: &[&Function], pos: Loc) -> Vec<Decoration> {
    let selected = match select_local(items, pos) {
        Some(l) => l,
        None => return Vec::new(),
    };
    let mut all: Vec<Decoration> = Vec::new();
    let mk = |kind: DecoKind, range: Range, text: String| Decoration {
        kind,
        range,
        hover_text: text,
        local: selected,
        overlapped: false,
    };
    // lifetimes
    for f in items {
        for d in &f.decls {
            if d.local() == selected {
                for r in lifetime_ranges(d) {
                    push_unique(&mut all, mk(DecoKind::Lifetime, r, lifetime_text(d)));
                }
            }
        }
    }
    // borrows and moves
    let mut imm = Vec::new();
    let mut mutb = Vec::new();
    let mut moves = Vec::new();
    let mut calls = Vec::new();
    for f in items {
        for bb in &f.basic_blocks {
            for st in &bb.statements {
                if let MirStatement::Assign { rval: Some(rv), .. } = st {
                    match rv {
                        MirRval::Borrow { target_local, range, mutable, .. } if *target_local == selected => {
                            if *mutable {
                                mutb.push(*range);
                            } else {
                                imm.push(*range);
                            }
                        }
                        MirRval::Move { target_local, range } if *target_local == selected => {
                            moves.push(*range);
                        }
                        _ => {}
                    }
                }
            }
            if let Some(MirTerminator::Call { destination_local, fn_span }) = &bb.terminator {
                if *destination_local == selected {
                    calls.push(*fn_span);
                }
            }
        }
    }
    for r in imm {
        push_unique(&mut all, mk(DecoKind::ImmBorrow, r, "immutable borrow".to_string()));
    }
    for r in mutb {
        push_unique(&mut all, mk(DecoKind::MutBorrow, r, "mutable borrow".to_string()));
    }
    for r in moves {
        push_unique(&mut all, mk(DecoKind::Move, r, "variable moved".to_string()));
    }
    for r in calls {
        push_unique(&mut all, mk(DecoKind::Call, r, "function call".to_string()));
    }
    // outlives
    for f in items {
        for d in &f.decls {
            if d.local() == selected {
                let lifetime = lifetime_ranges(d);
                let must = merge_ranges(d.must_live_at());
                for r in eliminate_ranges(&must, &lifetime) {
                    push_unique(&mut all, mk(DecoKind::Outlive, r, outlive_text(d)));
                }
            }
        }
    }
    // overlap elimination
    let mut result = Vec::new();
    for i in 0..all.len() {
        split_overlaps(&all[i], &all[i + 1..], &mut result);
    }
    result
}

// ---------------------------------------------------------------------------
// Position <-> Loc conversion (line based, `\r\n` tolerant)
// ---------------------------------------------------------------------------

pub fn position_to_loc(text: &str, line: u32, character: u32) -> Loc {
    let total = text.chars().count() as u64;
    let mut acc: u64 = 0;
    for (i, l) in text.lines().enumerate() {
        if i as u64 == line as u64 {
            let off = acc + character as u64;
            if off < total {
                return off as Loc;
            } else {
                return 0;
            }
        }
        acc += l.chars().count() as u64 + 1;
    }
    0
}

pub fn loc_to_position(text: &str, loc: Loc) -> (u32, u32) {
    let mut acc: u64 = 0;
    let loc = loc as u64;
    for (i, l) in text.lines().enumerate() {
        let len = l.chars().count() as u64;
        if acc <= loc && loc <= acc + len {
            return (i as u32, (loc - acc) as u32);
        }
        acc += len + 1;
    }
    (0, 0)
}
