//! Analysis backend shared by the LSP server and the `check` command.

use crate::json::{self, Value};
use crate::models::{self, Workspace};
use crate::toolchain;
use crate::{cargo, log_info, log_warn};
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread::JoinHandle;

const ANALYZE_TARGET: &str = "rustowl::lsp::analyze";
const BACKEND_TARGET: &str = "rustowl::lsp::backend";

/// Interface used to report progress to the LSP client.
pub trait ProgressClient: Send + Sync {
    /// Send `window/workDoneProgress/create` and wait for the response.
    fn create_progress(&self, token: &str);
    fn progress(&self, token: &str, value: Value);
}

#[derive(Clone, Debug)]
pub enum Target {
    Cargo { workspace_root: PathBuf, package: String, target_dir: PathBuf, total: usize },
    File(PathBuf),
}

#[derive(Default)]
struct State {
    roots: Vec<Target>,
    analyzed: Option<Workspace>,
    running: usize,
}

pub struct Backend {
    state: Mutex<State>,
    /// running child processes; the lock is held while a target is being prepared
    processes: Mutex<Vec<Child>>,
    client: Option<Arc<dyn ProgressClient>>,
    pub all_targets: bool,
    pub all_features: bool,
    sysroot: Mutex<Option<PathBuf>>,
    /// how to handle toolchain setup failures
    exit_on_toolchain_error: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Status {
    Finished,
    Analyzing,
    Error,
}

impl Status {
    pub fn name(self) -> &'static str {
        match self {
            Status::Finished => "finished",
            Status::Analyzing => "analyzing",
            Status::Error => "error",
        }
    }
}

pub struct CursorResult {
    pub decorations: Vec<Value>,
    pub is_analyzed: bool,
    pub path: Option<PathBuf>,
    pub status: Status,
}

impl Backend {
    pub fn new(client: Option<Arc<dyn ProgressClient>>, exit_on_toolchain_error: bool) -> Arc<Backend> {
        Arc::new(Backend {
            state: Mutex::new(State::default()),
            processes: Mutex::new(Vec::new()),
            client,
            all_targets: false,
            all_features: false,
            sysroot: Mutex::new(None),
            exit_on_toolchain_error,
        })
    }

    pub fn with_flags(client: Option<Arc<dyn ProgressClient>>, all_targets: bool, all_features: bool) -> Arc<Backend> {
        Arc::new(Backend {
            state: Mutex::new(State::default()),
            processes: Mutex::new(Vec::new()),
            client,
            all_targets,
            all_features,
            sysroot: Mutex::new(None),
            exit_on_toolchain_error: false,
        })
    }

    /// Ensure the toolchain is set up and return the sysroot.
    fn sysroot(&self) -> Result<PathBuf, ()> {
        let mut guard = self.sysroot.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(s) = guard.as_ref() {
            return Ok(s.clone());
        }
        match toolchain::setup_toolchain() {
            Ok(s) => {
                *guard = Some(s.clone());
                Ok(s)
            }
            Err(()) => {
                if self.exit_on_toolchain_error {
                    std::process::exit(1);
                }
                Err(())
            }
        }
    }

    fn push_root(&self, target: Target) {
        let mut st = self.state.lock().unwrap_or_else(|e| e.into_inner());
        let dup = st.roots.iter().any(|r| match (r, &target) {
            (Target::Cargo { workspace_root: a, .. }, Target::Cargo { workspace_root: b, .. }) => a == b,
            (Target::File(a), Target::File(b)) => a == b,
            _ => false,
        });
        if !dup {
            st.roots.push(target);
        }
    }

    fn target_from_metadata(meta: cargo::Metadata, fallback: &Path) -> Target {
        match meta.root_package {
            Some(pkg) => Target::Cargo {
                workspace_root: meta.workspace_root,
                package: pkg.name,
                target_dir: meta.target_directory,
                total: meta.packages.len(),
            },
            None => Target::File(fallback.to_path_buf()),
        }
    }

    /// Register an analysis target. Returns `false` when the path is invalid.
    pub fn add_root(&self, path: &Path) -> Result<bool, ()> {
        let sysroot = self.sysroot()?;
        if path.is_file() {
            let parent = path.parent().unwrap_or(Path::new(""));
            let target = match cargo::metadata_with_toolchain(&sysroot, parent) {
                Some(meta) => Self::target_from_metadata(meta, path),
                None => Target::File(path.to_path_buf()),
            };
            self.push_root(target);
            Ok(true)
        } else if path.is_dir() {
            match cargo::metadata_with_toolchain(&sysroot, path) {
                Some(meta) => {
                    self.push_root(Self::target_from_metadata(meta, path));
                    Ok(true)
                }
                None => {
                    log_warn!(ANALYZE_TARGET, "Invalid analysis target: {}", path.display());
                    Ok(false)
                }
            }
        } else {
            log_warn!(ANALYZE_TARGET, "Invalid analysis target: {}", path.display());
            Ok(false)
        }
    }

    /// Kill all running analysis processes.
    pub fn stop_processes(&self) {
        let mut procs = self.processes.lock().unwrap_or_else(|e| e.into_inner());
        for child in procs.iter_mut() {
            let _ = child.kill();
            let _ = child.wait();
        }
        procs.clear();
    }

    /// (Re)start the analysis of all registered targets.
    pub fn analyze_all(self: &Arc<Self>) -> Vec<JoinHandle<()>> {
        log_info!(BACKEND_TARGET, "wait 100ms for rust-analyzer");
        std::thread::sleep(std::time::Duration::from_millis(100));
        log_info!(BACKEND_TARGET, "stop running analysis processes");
        self.stop_processes();
        log_info!(BACKEND_TARGET, "start analysis");
        let roots: Vec<Target> = {
            let st = self.state.lock().unwrap_or_else(|e| e.into_inner());
            st.roots.clone()
        };
        log_info!(BACKEND_TARGET, "analyze {} packages...", roots.len());
        let sysroot = match self.sysroot.lock().unwrap_or_else(|e| e.into_inner()).clone() {
            Some(s) => s,
            None => toolchain::sysroot_dir(),
        };
        let mut handles = Vec::new();
        for root in roots {
            let me = Arc::clone(self);
            let sysroot = sysroot.clone();
            {
                let mut st = self.state.lock().unwrap_or_else(|e| e.into_inner());
                st.running += 1;
            }
            handles.push(std::thread::spawn(move || {
                me.analyze_target(&root, &sysroot);
                let mut st = me.state.lock().unwrap_or_else(|e| e.into_inner());
                st.running = st.running.saturating_sub(1);
            }));
        }
        handles
    }

    fn merge_line(&self, line: &str) -> bool {
        if let Some(ws) = models::parse_workspace_line(line) {
            let mut st = self.state.lock().unwrap_or_else(|e| e.into_inner());
            match st.analyzed.as_mut() {
                Some(a) => a.merge(ws),
                None => st.analyzed = Some(ws),
            }
            true
        } else {
            false
        }
    }

    fn analyze_target(&self, target: &Target, sysroot: &Path) {
        match target {
            Target::Cargo { workspace_root, package, target_dir, total } => {
                self.analyze_cargo(sysroot, workspace_root, package, target_dir, *total)
            }
            Target::File(path) => self.analyze_file(sysroot, path),
        }
    }

    fn analyze_cargo(&self, sysroot: &Path, workspace_root: &Path, package: &str, target_dir: &Path, total: usize) {
        let token = crate::util::uuid_v4();
        if let Some(client) = &self.client {
            client.create_progress(&token);
            client.progress(
                &token,
                json::obj(vec![
                    ("kind", Value::str("begin")),
                    ("title", Value::str("RustOwl")),
                    ("cancellable", Value::Bool(false)),
                    ("percentage", Value::from_u64(0)),
                ]),
            );
        }
        let owl_target_dir = target_dir.join("owl");
        let child = {
            let mut procs = self.processes.lock().unwrap_or_else(|e| e.into_inner());
            log_info!(ANALYZE_TARGET, "clear cargo cache");
            let mut clean = toolchain::cargo_command(sysroot);
            clean
                .arg("clean")
                .arg("--package")
                .arg(package)
                .env("CARGO_TARGET_DIR", &owl_target_dir)
                .current_dir(workspace_root)
                .stdin(Stdio::null())
                .stdout(Stdio::null())
                .stderr(Stdio::null());
            let _ = clean.status();

            let mut check = toolchain::cargo_command(sysroot);
            check.arg("check").arg("--workspace");
            if self.all_targets {
                check.arg("--all-targets");
            }
            if self.all_features {
                check.arg("--all-features");
            }
            check
                .arg("--keep-going")
                .arg("--message-format=json")
                .env("CARGO_TARGET_DIR", &owl_target_dir)
                .env("RUSTOWL_CACHE_DIR", owl_target_dir.join("cache"))
                .current_dir(workspace_root)
                .stdin(Stdio::null())
                .stdout(Stdio::piped())
                .stderr(Stdio::inherit());
            log_info!(ANALYZE_TARGET, "start analyzing package {}", package);
            match check.spawn() {
                Ok(mut child) => {
                    let stdout = child.stdout.take();
                    procs.push(child);
                    stdout
                }
                Err(e) => {
                    crate::panic_message(
                        "tokio-runtime-worker",
                        "/workspace/src/lsp/analyze.rs:189:14",
                        &format!("called `Result::unwrap()` on an `Err` value: {:?}", e),
                    );
                    None
                }
            }
        };
        if let Some(stdout) = child {
            let reader = BufReader::new(stdout);
            let mut checked: u64 = 0;
            for line in reader.lines() {
                let line = match line {
                    Ok(l) => l,
                    Err(_) => break,
                };
                if let Ok(v) = json::parse(&line) {
                    if v.get("reason").and_then(|r| r.as_str()) == Some("compiler-artifact") {
                        let name = v
                            .get("target")
                            .and_then(|t| t.get("name"))
                            .and_then(|n| n.as_str())
                            .unwrap_or("")
                            .to_string();
                        log_info!(ANALYZE_TARGET, "crate {} checked", name);
                        checked += 1;
                        if let Some(client) = &self.client {
                            let percentage = if total > 0 { checked * 100 / total as u64 } else { 100 };
                            client.progress(
                                &token,
                                json::obj(vec![
                                    ("kind", Value::str("report")),
                                    ("message", Value::String(format!("{} analyzed", name))),
                                    ("cancellable", Value::Bool(false)),
                                    ("percentage", Value::from_u64(percentage)),
                                ]),
                            );
                        }
                        continue;
                    }
                    if v.get("reason").is_some() {
                        continue;
                    }
                    if let Ok(ws) = models::de_workspace(&v) {
                        let mut st = self.state.lock().unwrap_or_else(|e| e.into_inner());
                        match st.analyzed.as_mut() {
                            Some(a) => a.merge(ws),
                            None => st.analyzed = Some(ws),
                        }
                    }
                }
            }
            log_info!(ANALYZE_TARGET, "stdout closed");
            self.reap_finished();
        }
        if let Some(client) = &self.client {
            client.progress(&token, json::obj(vec![("kind", Value::str("end"))]));
        }
    }

    fn analyze_file(&self, sysroot: &Path, path: &Path) {
        let child = {
            let mut procs = self.processes.lock().unwrap_or_else(|e| e.into_inner());
            let mut cmd: Command = toolchain::rustowlc_command(sysroot);
            cmd.arg(format!("--sysroot={}", sysroot.display()))
                .arg("--crate-type=lib")
                .arg("-o/dev/null")
                .arg(path)
                .stdin(Stdio::null())
                .stdout(Stdio::piped())
                .stderr(Stdio::inherit());
            log_info!(ANALYZE_TARGET, "start analyzing {}", path.display());
            match cmd.spawn() {
                Ok(mut child) => {
                    let stdout = child.stdout.take();
                    procs.push(child);
                    stdout
                }
                Err(e) => {
                    crate::panic_message(
                        "tokio-runtime-worker",
                        "/workspace/src/lsp/analyze.rs:222:41",
                        &format!("called `Result::unwrap()` on an `Err` value: {:?}", e),
                    );
                    None
                }
            }
        };
        if let Some(stdout) = child {
            let reader = BufReader::new(stdout);
            for line in reader.lines() {
                let line = match line {
                    Ok(l) => l,
                    Err(_) => break,
                };
                self.merge_line(&line);
            }
            log_info!(ANALYZE_TARGET, "stdout closed");
            self.reap_finished();
        }
    }

    /// Remove finished children from the process list.
    fn reap_finished(&self) {
        let mut procs = self.processes.lock().unwrap_or_else(|e| e.into_inner());
        procs.retain_mut(|c| match c.try_wait() {
            Ok(Some(_)) => false,
            Ok(None) => true,
            Err(_) => false,
        });
    }

    pub fn clear_analyzed(&self) {
        let mut st = self.state.lock().unwrap_or_else(|e| e.into_inner());
        st.analyzed = None;
    }

    pub fn analyzed_file_count(&self) -> usize {
        let st = self.state.lock().unwrap_or_else(|e| e.into_inner());
        st.analyzed.as_ref().map(|a| a.file_count()).unwrap_or(0)
    }

    pub fn cursor(&self, path: Option<PathBuf>, line: u32, character: u32) -> CursorResult {
        let st = self.state.lock().unwrap_or_else(|e| e.into_inner());
        let is_analyzed = st.analyzed.is_some();
        let mut status = if st.running > 0 { Status::Analyzing } else { Status::Finished };
        let mut decorations = Vec::new();
        if let Some(p) = &path {
            let items: Vec<&models::Function> = st
                .analyzed
                .as_ref()
                .and_then(|a| a.find_file(p))
                .map(|f| f.items.iter().collect())
                .unwrap_or_default();
            if items.is_empty() {
                if status != Status::Analyzing {
                    status = Status::Error;
                }
            } else {
                let text = std::fs::read_to_string(p).unwrap_or_default();
                let loc = models::position_to_loc(&text, line, character);
                for d in models::compute_decorations(&items, loc) {
                    let (sl, sc) = models::loc_to_position(&text, d.range.from);
                    let (el, ec) = models::loc_to_position(&text, d.range.until);
                    decorations.push(json::obj(vec![
                        ("type", Value::str(d.kind.name())),
                        (
                            "range",
                            json::obj(vec![
                                (
                                    "start",
                                    json::obj(vec![("line", Value::from_u64(sl as u64)), ("character", Value::from_u64(sc as u64))]),
                                ),
                                (
                                    "end",
                                    json::obj(vec![("line", Value::from_u64(el as u64)), ("character", Value::from_u64(ec as u64))]),
                                ),
                            ]),
                        ),
                        ("hover_text", Value::String(d.hover_text.clone())),
                        ("overlapped", Value::Bool(d.overlapped)),
                        (
                            "local",
                            json::obj(vec![
                                ("id", Value::from_u64(d.local.id as u64)),
                                ("fn_id", Value::from_u64(d.local.fn_id as u64)),
                            ]),
                        ),
                    ]));
                }
            }
        }
        CursorResult { decorations, is_analyzed, path, status }
    }
}
