//! Minimal URL handling (enough for `file://` URIs) mimicking the `url` crate.

use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct Url {
    pub scheme: String,
    pub host: Option<String>,
    /// path with dot segments resolved, still percent-encoded
    pub path: String,
}

fn is_scheme_start(c: char) -> bool {
    c.is_ascii_alphabetic()
}
fn is_scheme_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.'
}

fn is_dot(seg: &str) -> bool {
    seg == "." || seg.eq_ignore_ascii_case("%2e")
}
fn is_dotdot(seg: &str) -> bool {
    seg == ".."
        || seg.eq_ignore_ascii_case(".%2e")
        || seg.eq_ignore_ascii_case("%2e.")
        || seg.eq_ignore_ascii_case("%2e%2e")
}

/// Parse an absolute URL. Errors are formatted like `url::ParseError`'s Display.
pub fn parse(input: &str) -> Result<Url, String> {
    let s = input.trim_matches(|c: char| c <= ' ');
    let s: String = s.chars().filter(|c| *c != '\t' && *c != '\n' && *c != '\r').collect();
    // scheme
    let mut chars = s.chars();
    let first = match chars.next() {
        Some(c) => c,
        None => return Err("relative URL without a base".to_string()),
    };
    if !is_scheme_start(first) {
        return Err("relative URL without a base".to_string());
    }
    let colon = match s.find(':') {
        Some(p) => p,
        None => return Err("relative URL without a base".to_string()),
    };
    let scheme_part = &s[..colon];
    if !scheme_part.chars().all(is_scheme_char) {
        return Err("relative URL without a base".to_string());
    }
    let scheme = scheme_part.to_ascii_lowercase();
    let rest = &s[colon + 1..];
    let special = matches!(scheme.as_str(), "http" | "https" | "ws" | "wss" | "ftp" | "file");
    let (host, path_part) = if let Some(after) = rest.strip_prefix("//") {
        let end = after.find(|c| c == '/' || c == '?' || c == '#').unwrap_or(after.len());
        let authority = &after[..end];
        let path = &after[end..];
        let host = authority.rsplit('@').next().unwrap_or(authority);
        if special && scheme != "file" && host.is_empty() {
            return Err("empty host".to_string());
        }
        (Some(host.to_ascii_lowercase()), path)
    } else if special {
        // special schemes without "//" (e.g. "file:/path")
        let p = rest.trim_start_matches(['/', '\\']);
        (Some(String::new()), &rest[rest.len() - p.len() - if rest.len() > p.len() { 1 } else { 0 }..])
    } else {
        (None, rest)
    };
    // strip query/fragment
    let path_only = {
        let end = path_part.find(|c| c == '?' || c == '#').unwrap_or(path_part.len());
        &path_part[..end]
    };
    let path = if host.is_some() || path_only.starts_with('/') {
        normalize_path(path_only)
    } else {
        path_only.to_string()
    };
    Ok(Url { scheme, host, path })
}

fn normalize_path(p: &str) -> String {
    if p.is_empty() {
        return "/".to_string();
    }
    let raw = p.strip_prefix('/').unwrap_or(p);
    let segs: Vec<&str> = raw.split('/').collect();
    let mut out: Vec<String> = Vec::new();
    let n = segs.len();
    for (i, seg) in segs.iter().enumerate() {
        let last = i + 1 == n;
        if is_dotdot(seg) {
            out.pop();
            if last {
                out.push(String::new());
            }
        } else if is_dot(seg) {
            if last {
                out.push(String::new());
            }
        } else {
            out.push(seg.to_string());
        }
    }
    format!("/{}", out.join("/"))
}

fn percent_decode(s: &str) -> Option<Vec<u8>> {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 {
            let h = std::str::from_utf8(&b[i + 1..i + 3]).ok()?;
            if let Ok(v) = u8::from_str_radix(h, 16) {
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    Some(out)
}

impl Url {
    /// Convert a `file:` URL to a path (Unix semantics of `Url::to_file_path`).
    pub fn to_file_path(&self) -> Result<PathBuf, ()> {
        if self.scheme != "file" {
            return Err(());
        }
        match &self.host {
            Some(h) if !h.is_empty() && h != "localhost" => return Err(()),
            None => return Err(()),
            _ => {}
        }
        let raw = self.path.strip_prefix('/').unwrap_or(&self.path);
        let mut bytes: Vec<u8> = Vec::new();
        for seg in raw.split('/') {
            bytes.push(b'/');
            let dec = percent_decode(seg).ok_or(())?;
            if dec.contains(&b'/') {
                return Err(());
            }
            bytes.extend_from_slice(&dec);
        }
        if bytes.is_empty() {
            bytes.push(b'/');
        }
        use std::os::unix::ffi::OsStringExt;
        Ok(PathBuf::from(std::ffi::OsString::from_vec(bytes)))
    }
}
