        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 {
            let h = std::str::from_utf8(&b[i + 1..i + 3]).ok()?;
            if let Ok(v) = u8::from_str_radix(h, 16) {
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    Some(out)
}

impl Url {
    /// Convert a `file:` URL to a path (Unix semantics of `Url::to_file_path`).
    pub fn to_file_path(&self) -> Result<PathBuf, ()> {
        if self.scheme != "file" {
            return Err(());
        }
        match &self.host {
            Some(h) if !h.is_empty() && h != "localhost" => return Err(()),
            None => return Err(()),
            _ => {}
        }
        let raw = self.path.strip_prefix('/').unwrap_or(&self.path);
        let mut bytes: Vec<u8> = Vec::new();
        for seg in raw.split('/') {
            bytes.push(b'/');
            let dec = percent_decode(seg).ok_or(())?;
            if dec.contains(&b'/') {
                return Err(());
            }
            bytes.extend_from_slice(&dec);
        }
        if bytes.is_empty() {
            bytes.push(b'/');
        }
        use std::os::unix::ffi::OsStringExt;
        Ok(PathBuf::from(std::ffi::OsString::from_vec(bytes)))
    }
}
