    let trace_f = opt_validator(&|x: &Value| match x {
        Value::String(t) if t == "off" || t == "messages" || t == "verbose" => Ok(()),
        Value::String(t) => Err(format!("unknown variant `{}`, expected one of `off`, `messages`, `verbose`", t)),
        other => Err(format!("invalid type: {}, expected string", other.unexpected())),
