            Ok(())
        }
        other => Err(format!("invalid type: {}, expected a sequence", other.unexpected())),
    });
    let client_info_f = opt_validator(&|x: &Value| {
        let s = sv(x, "ClientInfo", 2)?;
        let name_f = |y: &Value| de_string(y).map(|_| ());
        let ver_f = opt_validator(&|y: &Value| de_string(y).map(|_| ()));
        s.validate(&[("name", true, &name_f), ("version", false, &ver_f)])
    });
    let locale_f = opt_validator(&|x: &Value| de_string(x).map(|_| ()));
    let token_f = opt_validator(&|x: &Value| match x {
        Value::Number(_) | Value::String(_) => Ok(()),
        other => Err(format!("invalid type: {}, expected number or string", other.unexpected())),
    });
    s.validate(&[
        ("processId", false, &pid_f),
        ("rootPath", false, &root_path_f),
        ("rootUri", false, &root_uri_f),
        ("initializationOptions", false, &init_opts_f),
        ("capabilities", true, &caps_f),
        ("trace", false, &trace_f),
        ("workspaceFolders", false, &folders_f),
        ("clientInfo", false, &client_info_f),
        ("locale", false, &locale_f),
        ("workDoneToken", false, &token_f),
    ])?;
    let root_uri = match s.opt(2, "rootUri") {
        None | Some(Value::Null) => None,
        Some(x) => Some(de_url(x)?),
    };
    let mut folders = Vec::new();
    if let Some(Value::Array(a)) = s.opt(6, "workspaceFolders") {
        for f in a {
            folders.push(de_workspace_folder(f)?);
        }
    }
    Ok(InitParams { root_uri, workspace_folders: folders })
}

