        json::obj(vec![
            (
                "textDocumentSync",
                json::obj(vec![
                    ("openClose", Value::Bool(true)),
                    ("change", Value::from_u64(2)),
                    ("save", Value::Bool(true)),
                ]),
            ),
            (
                "workspace",
                json::obj(vec![(
                    "workspaceFolders",
                    json::obj(vec![("supported", Value::Bool(true)), ("changeNotifications", Value::Bool(true))]),
                )]),
            ),
        ]),
    )])
}

fn handle_initialize(server: Arc<Server>, id: Id, params: Option<Value>, canceled: Arc<AtomicBool>) {
    let params = match params {
        None => {
            server.set_phase(Phase::Uninitialized);
            server.respond_err(&id, ERR_INVALID_PARAMS, "Missing params field");
            return;
        }
        Some(p) => p,
    };
    let parsed = match de_init_params(&params) {
        Ok(p) => p,
        Err(e) => {
            server.set_phase(Phase::Uninitialized);
            server.respond_err(&id, ERR_INVALID_PARAMS, &e);
            return;
        }
    };
    let mut roots: Vec<url::Url> = Vec::new();
    if let Some(r) = parsed.root_uri {
        roots.push(r);
    }
    roots.extend(parsed.workspace_folders);
    for r in roots {
        if canceled.load(Ordering::SeqCst) {
            return;
        }
        if let Some(p) = uri_to_path(&r) {
            let _ = server.backend.add_root(&p);
        }
    }
    if canceled.load(Ordering::SeqCst) {
        return;
    }
    server.backend.analyze_all();
    if canceled.load(Ordering::SeqCst) {
        return;
    }
    server.set_phase(Phase::Initialized);
    server.respond_ok(&id, &capabilities());
}

fn handle_shutdown(server: Arc<Server>, id: Id) {
    server.backend.stop_processes();
    server.set_phase(Phase::ShutDown);
    server.respond_ok(&id, &Value::Null);
}

fn handle_cursor(server: Arc<Server>, id: Id, params: Option<Value>) {
    let params = match params {
        None => {
            server.respond_err(&id, ERR_INVALID_PARAMS, "Missing params field");
            return;
        }
        Some(p) => p,
    };
    let cp = match de_cursor_params(&params) {
        Ok(p) => p,
        Err(e) => {
            server.respond_err(&id, ERR_INVALID_PARAMS, &e);
            return;
        }
    };
    let path = uri_to_path(&cp.uri).filter(|p| p.is_file());
    let res = server.backend.cursor(path, cp.line, cp.character);
    let result = json::obj(vec![
        ("decorations", Value::Array(res.decorations)),
        ("is_analyzed", Value::Bool(res.is_analyzed)),
        (
            "path",
            match &res.path {
                Some(p) => Value::String(p.to_string_lossy().into_owned()),
                None => Value::Null,
            },
        ),
        ("status", Value::str(res.status.name())),
    ]);
    server.respond_ok(&id, &result);
}

fn text_document_uri(params: &Value) -> Option<url::Url> {
    let td = params.get("textDocument")?;
    de_url(td.get("uri")?).ok()
}

fn handle_did_open(server: Arc<Server>, params: Value) {
    let td = match params.get("textDocument") {
        Some(t) => t,
        None => return,
    };
    let uri = match td.get("uri").map(de_url) {
        Some(Ok(u)) => u,
        _ => return,
    };
    if td.get("languageId").map(|v| de_string(v).is_err()).unwrap_or(true) {
        return;
    }
    if td.get("version").map(|v| de_i32(v).is_err()).unwrap_or(true) {
        return;
    }
    if td.get("text").map(|v| de_string(v).is_err()).unwrap_or(true) {
        return;
    }
    if let Some(path) = uri_to_path(&uri) {
        if path.is_file() {
            if server.backend.add_root(&path).is_err() {
                return;
            }
            server.backend.analyze_all();
        }
    }
}

fn handle_did_change(server: Arc<Server>, params: Value) {
    if text_document_uri(&params).is_none() {
        return;
    }
    if !matches!(params.get("contentChanges"), Some(Value::Array(_))) {
        return;
    }
    server.backend.clear_analyzed();
}

fn handle_did_change_workspace_folders(server: Arc<Server>, params: Value) {
    let event = match params.get("event") {
        Some(e) => e,
        None => return,
    };
    let added = match event.get("added") {
        Some(Value::Array(a)) => a,
        _ => return,
    };
    if !matches!(event.get("removed"), Some(Value::Array(_))) {
        return;
    }
    let mut uris = Vec::new();
    for f in added {
        match de_workspace_folder(f) {
            Ok(u) => uris.push(u),
            Err(_) => return,
        }
    }
    if uris.is_empty() {
        return;
    }
    for u in uris {
        if let Some(p) = uri_to_path(&u) {
            let _ = server.backend.add_root(&p);
        }
    }
    server.backend.analyze_all();
}

const REQUEST_METHODS: &[&str] = &["initialize", "shutdown", "rustowl/cursor"];
const NOTIFICATION_METHODS: &[&str] = &[
    "initialized",
    "exit",
    "textDocument/didOpen",
    "textDocument/didChange",
    "textDocument/didSave",
    "textDocument/didClose",
    "workspace/didChangeWorkspaceFolders",
    "$/cancelRequest",
];

// ---------------------------------------------------------------------------
// Main loop
// ---------------------------------------------------------------------------

pub fn run() -> ! {
    eprintln!("RustOwl v{}", crate::cli::VERSION);
    eprintln!("This is an LSP server. You can use --help flag to show help.");
    let transport = Arc::new(Transport::new());
    let backend = Backend::new(Some(transport.clone() as Arc<dyn ProgressClient>), true);
    let server = Arc::new(Server {
        transport: Arc::clone(&transport),
        backend,
        phase: Mutex::new(Phase::Uninitialized),
        inflight: Mutex::new(HashMap::new()),
    });
    let mut handlers: Vec<std::thread::JoinHandle<()>> = Vec::new();
    let mut reader = FrameReader { inner: std::io::stdin(), buf: Vec::new() };
    loop {
        let frame = reader.next_frame();
        let body = match frame {
            Frame::Eof => break,
            Frame::Error => {
                transport.send_error(&Id::Null, ERR_PARSE, "Parse error", None);
                break;
            }
            Frame::Message(b) => b,
        };
        if server.phase() == Phase::Exited {
            // tower-lsp stops servicing after `exit`; it never terminates on its own.
            loop {
                std::thread::park();
            }
        }
        let value = match json::parse(&body) {
            Ok(v) => v,
            Err(_) => {
                transport.send_error(&Id::Null, ERR_PARSE, "Parse error", None);
                break;
            }
        };
        let obj = match &value {
            Value::Object(m) => m,
            _ => {
                transport.send_error(&Id::Null, ERR_INVALID_REQUEST, "Invalid request", None);
                break;
            }
        };
        if obj.get("jsonrpc").and_then(|v| v.as_str()) != Some("2.0") {
            transport.send_error(&Id::Null, ERR_INVALID_REQUEST, "Invalid request", None);
            break;
        }
        let id = match obj.get("id") {
            None => None,
            Some(v) => match Id::from_value(v) {
                Some(i) => Some(i),
                None => {
                    transport.send_error(&Id::Null, ERR_INVALID_REQUEST, "Invalid request", None);
                    break;
                }
            },
        };
        let has_method = obj.contains_key("method");
        if !has_method && (obj.contains_key("result") || obj.contains_key("error")) {
            // response from the client
            if let Some(id) = id {
                let v = obj.get("result").cloned().unwrap_or(Value::Null);
                transport.deliver_response(&id, v);
            }
            continue;
        }
        let method = match obj.get("method") {
            None => String::new(),
            Some(Value::String(s)) => s.clone(),
            Some(_) => {
                transport.send_error(&Id::Null, ERR_INVALID_REQUEST, "Invalid request", None);
                break;
            }
        };
        let params = obj.get("params").cloned();
        handlers.retain(|h| !h.is_finished());
        match id {
            Some(id) => {
                if let Some(h) = dispatch_request(&server, id, &method, params) {
                    handlers.push(h);
                }
            }
            None => {
                if let Some(h) = dispatch_notification(&server, &method, params) {
                    handlers.push(h);
                }
            }
        }
    }
    for h in handlers {
        let _ = h.join();
    }
    std::process::exit(0);
}

fn dispatch_request(server: &Arc<Server>, id: Id, method: &str, params: Option<Value>) -> Option<std::thread::JoinHandle<()>> {
    let t = &server.transport;
    if !REQUEST_METHODS.contains(&method) {
        t.send_error(&id, ERR_METHOD_NOT_FOUND, "Method not found", Some(&Value::String(method.to_string())));
        return None;
    }
    let phase = server.phase();
    match method {
        "initialize" => {
            if phase != Phase::Uninitialized {
                t.send_error(&id, ERR_INVALID_REQUEST, "Invalid request", None);
                return None;
            }
            server.set_phase(Phase::Initializing);
            let canceled = server.begin_request(&id);
            let s = Arc::clone(server);
            Some(std::thread::spawn(move || handle_initialize(s, id, params, canceled)))
        }
        "shutdown" => {
            match phase {
                Phase::Uninitialized | Phase::Initializing => {
                    t.send_error(&id, ERR_NOT_INITIALIZED, "Server not initialized", None);
                    return None;
                }
                Phase::ShutDown | Phase::Exited => {
                    t.send_error(&id, ERR_INVALID_REQUEST, "Invalid request", None);
                    return None;
                }
                Phase::Initialized => {}
            }
            if let Some(p) = params {
                t.send_error(&id, ERR_INVALID_PARAMS, &format!("Unexpected params: {}", json::to_string(&p)), None);
                return None;
            }
            server.begin_request(&id);
            let s = Arc::clone(server);
            Some(std::thread::spawn(move || handle_shutdown(s, id)))
        }
        "rustowl/cursor" => {
            match phase {
                Phase::Uninitialized | Phase::Initializing => {
                    t.send_error(&id, ERR_NOT_INITIALIZED, "Server not initialized", None);
                    return None;
                }
                Phase::ShutDown | Phase::Exited => {
                    t.send_error(&id, ERR_INVALID_REQUEST, "Invalid request", None);
                    return None;
                }
                Phase::Initialized => {}
            }
            server.begin_request(&id);
            let s = Arc::clone(server);
            Some(std::thread::spawn(move || handle_cursor(s, id, params)))
        }
        _ => None,
    }
}

fn dispatch_notification(server: &Arc<Server>, method: &str, params: Option<Value>) -> Option<std::thread::JoinHandle<()>> {
    if !NOTIFICATION_METHODS.contains(&method) {
        return None;
    }
    match method {
        "exit" => {
            server.set_phase(Phase::Exited);
            server.cancel_all();
            return None;
        }
        "$/cancelRequest" => {
            if let Some(p) = params {
                if let Some(idv) = p.get("id") {
                    if let Some(id) = Id::from_value(idv) {
                        server.cancel(&id);
                    }
                }
            }
            return None;
        }
        _ => {}
    }
    if server.phase() != Phase::Initialized {
        return None;
    }
    let params = params?;
    let s = Arc::clone(server);
    match method {
        "textDocument/didOpen" => Some(std::thread::spawn(move || handle_did_open(s, params))),
        "textDocument/didChange" => Some(std::thread::spawn(move || handle_did_change(s, params))),
        "workspace/didChangeWorkspaceFolders" => {
            Some(std::thread::spawn(move || handle_did_change_workspace_folders(s, params)))
        }
        _ => None,
    }
}
