//! LSP server (JSON-RPC over stdio) with tower-lsp compatible behaviour.

use crate::backend::{Backend, ProgressClient};
use crate::json::{self, Number, Value};
use crate::url;
use std::collections::{BTreeMap, HashMap};
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, Mutex};

// ---------------------------------------------------------------------------
// JSON-RPC ids
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Id {
    Number(i64),
    String(String),
    Null,
}

impl Id {
    fn to_json(&self) -> String {
        match self {
            Id::Number(n) => n.to_string(),
            Id::String(s) => {
                let mut o = String::new();
                json::write_string(s, &mut o);
                o
            }
            Id::Null => "null".to_string(),
        }
    }
    fn from_value(v: &Value) -> Option<Id> {
        match v {
            Value::Null => Some(Id::Null),
            Value::String(s) => Some(Id::String(s.clone())),
            Value::Number(Number::PosInt(n)) => i64::try_from(*n).ok().map(Id::Number),
            Value::Number(Number::NegInt(n)) => Some(Id::Number(*n)),
            _ => None,
        }
    }
}

// ---------------------------------------------------------------------------
// Transport
// ---------------------------------------------------------------------------

pub struct Transport {
    out: Mutex<()>,
    next_id: AtomicU64,
    pending: Mutex<HashMap<u64, Sender<Value>>>,
}

impl Transport {
    fn new() -> Self {
        Transport { out: Mutex::new(()), next_id: AtomicU64::new(0), pending: Mutex::new(HashMap::new()) }
    }

    fn send_raw(&self, body: &str) {
        let _g = self.out.lock().unwrap_or_else(|e| e.into_inner());
        let stdout = std::io::stdout();
        let mut h = stdout.lock();
        let _ = write!(h, "Content-Length: {}\r\n\r\n{}", body.len(), body);
        let _ = h.flush();
    }

    pub fn send_result(&self, id: &Id, result: &Value) {
        self.send_raw(&format!("{{\"jsonrpc\":\"2.0\",\"result\":{},\"id\":{}}}", json::to_string(result), id.to_json()));
    }

    pub fn send_error(&self, id: &Id, code: i64, message: &str, data: Option<&Value>) {
        let mut msg = String::new();
        json::write_string(message, &mut msg);
        let data_part = match data {
            Some(d) => format!(",\"data\":{}", json::to_string(d)),
            None => String::new(),
        };
        self.send_raw(&format!(
            "{{\"jsonrpc\":\"2.0\",\"error\":{{\"code\":{},\"message\":{}{}}},\"id\":{}}}",
            code,
            msg,
            data_part,
            id.to_json()
        ));
    }

    pub fn send_notification(&self, method: &str, params: &Value) {
        let mut m = String::new();
        json::write_string(method, &mut m);
        self.send_raw(&format!("{{\"jsonrpc\":\"2.0\",\"method\":{},\"params\":{}}}", m, json::to_string(params)));
    }

    pub fn send_request(&self, method: &str, params: &Value) -> Receiver<Value> {
        let id = self.next_id.fetch_add(1, Ordering::SeqCst);
        let (tx, rx) = channel();
        self.pending.lock().unwrap_or_else(|e| e.into_inner()).insert(id, tx);
        let mut m = String::new();
        json::write_string(method, &mut m);
        self.send_raw(&format!(
            "{{\"jsonrpc\":\"2.0\",\"method\":{},\"params\":{},\"id\":{}}}",
            m,
            json::to_string(params),
            id
        ));
        rx
    }

    fn deliver_response(&self, id: &Id, v: Value) {
        if let Id::Number(n) = id {
            if *n >= 0 {
                let tx = self.pending.lock().unwrap_or_else(|e| e.into_inner()).remove(&(*n as u64));
                if let Some(tx) = tx {
                    let _ = tx.send(v);
                }
            }
        }
    }
}

impl ProgressClient for Transport {
    fn create_progress(&self, token: &str) {
        let rx = self.send_request("window/workDoneProgress/create", &json::obj(vec![("token", Value::str(token))]));
        // wait for the client's answer (errors are ignored)
        let _ = rx.recv();
    }
    fn progress(&self, token: &str, value: Value) {
        self.send_notification("$/progress", &json::obj(vec![("token", Value::str(token)), ("value", value)]));
    }
}

// ---------------------------------------------------------------------------
// Framing
// ---------------------------------------------------------------------------

enum Frame {
    Message(String),
    Eof,
    Error,
}

struct FrameReader<R: Read> {
    inner: R,
    buf: Vec<u8>,
}

impl<R: Read> FrameReader<R> {
    fn fill(&mut self) -> bool {
        let mut tmp = [0u8; 8192];
        match self.inner.read(&mut tmp) {
            Ok(0) | Err(_) => false,
            Ok(n) => {
                self.buf.extend_from_slice(&tmp[..n]);
                true
            }
        }
    }

    fn find_header_end(&self) -> Option<(usize, usize)> {
        // returns (header_len, separator_len)
        let b = &self.buf;
        let mut i = 0;
        while i < b.len() {
            if b[i] == b'\n' {
                if i + 1 < b.len() && b[i + 1] == b'\n' {
                    return Some((i, 2));
                }
                if i + 2 < b.len() && b[i + 1] == b'\r' && b[i + 2] == b'\n' {
                    return Some((i, 3));
                }
            }
            i += 1;
        }
        None
    }

    fn next_frame(&mut self) -> Frame {
        loop {
            if let Some((hdr_end, sep_len)) = self.find_header_end() {
                let header = String::from_utf8_lossy(&self.buf[..hdr_end]).into_owned();
                let mut content_length: Option<usize> = None;
                let mut bad = false;
                for line in header.split('\n') {
                    let line = line.trim_end_matches('\r');
                    if line.is_empty() {
                        continue;
                    }
                    match line.split_once(':') {
                        Some((name, value)) => {
                            if name.trim() == "Content-Length" {
                                match value.trim().parse::<usize>() {
                                    Ok(n) => content_length = Some(n),
                                    Err(_) => bad = true,
                                }
                            }
                        }
                        None => bad = true,
                    }
                }
                let len = match content_length {
                    Some(n) if !bad => n,
                    _ => return Frame::Error,
                };
                let body_start = hdr_end + sep_len;
                while self.buf.len() < body_start + len {
                    if !self.fill() {
                        return Frame::Error;
                    }
                }
                let body = self.buf[body_start..body_start + len].to_vec();
                self.buf.drain(..body_start + len);
                return match String::from_utf8(body) {
                    Ok(s) => Frame::Message(s),
                    Err(_) => Frame::Error,
                };
            }
            if !self.fill() {
                if self.buf.iter().all(|c| c.is_ascii_whitespace()) {
                    return Frame::Eof;
                }
                return Frame::Error;
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Server state
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Phase {
    Uninitialized,
    Initializing,
    Initialized,
    ShutDown,
    Exited,
}

struct Inflight {
    canceled: Arc<AtomicBool>,
}

struct Server {
    transport: Arc<Transport>,
    backend: Arc<Backend>,
    phase: Mutex<Phase>,
    inflight: Mutex<HashMap<Id, Inflight>>,
}

const ERR_PARSE: i64 = -32700;
const ERR_INVALID_REQUEST: i64 = -32600;
const ERR_METHOD_NOT_FOUND: i64 = -32601;
const ERR_INVALID_PARAMS: i64 = -32602;
const ERR_NOT_INITIALIZED: i64 = -32002;
const ERR_CANCELED: i64 = -32800;

impl Server {
    fn phase(&self) -> Phase {
        *self.phase.lock().unwrap_or_else(|e| e.into_inner())
    }
    fn set_phase(&self, p: Phase) {
        *self.phase.lock().unwrap_or_else(|e| e.into_inner()) = p;
    }

    /// Register an in-flight request; returns its cancellation flag.
    fn begin_request(&self, id: &Id) -> Arc<AtomicBool> {
        let flag = Arc::new(AtomicBool::new(false));
        self.inflight
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .insert(id.clone(), Inflight { canceled: Arc::clone(&flag) });
        flag
    }

    /// Finish a request: returns true if the response may be sent.
    fn end_request(&self, id: &Id) -> bool {
        self.inflight.lock().unwrap_or_else(|e| e.into_inner()).remove(id).is_some()
    }

    fn respond_ok(&self, id: &Id, result: &Value) {
        if self.end_request(id) {
            self.transport.send_result(id, result);
        }
    }
    fn respond_err(&self, id: &Id, code: i64, message: &str) {
        if self.end_request(id) {
            self.transport.send_error(id, code, message, None);
        }
    }

    fn cancel(&self, id: &Id) {
        let entry = self.inflight.lock().unwrap_or_else(|e| e.into_inner()).remove(id);
        if let Some(e) = entry {
            e.canceled.store(true, Ordering::SeqCst);
            self.transport.send_error(id, ERR_CANCELED, "Canceled", None);
        }
    }

    fn cancel_all(&self) {
        let entries: Vec<(Id, Inflight)> = self.inflight.lock().unwrap_or_else(|e| e.into_inner()).drain().collect();
        for (id, e) in entries {
            e.canceled.store(true, Ordering::SeqCst);
            self.transport.send_error(&id, ERR_CANCELED, "Canceled", None);
        }
    }
}

// ---------------------------------------------------------------------------
// Params deserialization helpers (serde-like error messages)
// ---------------------------------------------------------------------------

type DeResult<T> = Result<T, String>;

fn de_u32(v: &Value) -> DeResult<u32> {
    match v {
        Value::Number(Number::PosInt(n)) if *n <= u32::MAX as u64 => Ok(*n as u32),
        Value::Number(Number::PosInt(n)) => Err(format!("invalid value: integer `{}`, expected u32", n)),
        Value::Number(Number::NegInt(n)) => Err(format!("invalid value: integer `{}`, expected u32", n)),
        other => Err(format!("invalid type: {}, expected u32", other.unexpected())),
    }
}

fn de_i32(v: &Value) -> DeResult<i32> {
    match v {
        Value::Number(Number::PosInt(n)) if *n <= i32::MAX as u64 => Ok(*n as i32),
        Value::Number(Number::NegInt(n)) if *n >= i32::MIN as i64 => Ok(*n as i32),
        Value::Number(Number::PosInt(n)) => Err(format!("invalid value: integer `{}`, expected i32", n)),
        Value::Number(Number::NegInt(n)) => Err(format!("invalid value: integer `{}`, expected i32", n)),
        other => Err(format!("invalid type: {}, expected i32", other.unexpected())),
    }
}

fn de_string(v: &Value) -> DeResult<String> {
    match v {
        Value::String(s) => Ok(s.clone()),
        other => Err(format!("invalid type: {}, expected a string", other.unexpected())),
    }
}

fn de_url(v: &Value) -> DeResult<url::Url> {
    let s = de_string(v)?;
    url::parse(&s).map_err(|e| format!("{}: {:?}", e, s))
}

/// Struct-like access: object fields by name or sequence elements by index.
struct SV<'a> {
    obj: Option<&'a BTreeMap<String, Value>>,
    seq: Option<&'a Vec<Value>>,
    name: &'static str,
    total: usize,
}

fn sv<'a>(v: &'a Value, name: &'static str, total: usize) -> DeResult<SV<'a>> {
    match v {
        Value::Object(m) => Ok(SV { obj: Some(m), seq: None, name, total }),
        Value::Array(a) => Ok(SV { obj: None, seq: Some(a), name, total }),
        other => Err(format!("invalid type: {}, expected struct {}", other.unexpected(), name)),
    }
}

impl<'a> SV<'a> {
    fn req(&self, idx: usize, field: &str) -> DeResult<&'a Value> {
        if let Some(m) = self.obj {
            m.get(field).ok_or_else(|| format!("missing field `{}`", field))
        } else {
            let s = self.seq.unwrap();
            s.get(idx).ok_or_else(|| format!("invalid length {}, expected struct {} with {} elements", s.len(), self.name, self.total))
        }
    }
    fn opt(&self, idx: usize, field: &str) -> Option<&'a Value> {
        if let Some(m) = self.obj {
            m.get(field)
        } else {
            self.seq.unwrap().get(idx)
        }
    }
    /// Validate present fields in key order with the given validators, then
    /// check required ones (in declaration order).
    fn validate(&self, fields: &[(&str, bool, &dyn Fn(&Value) -> DeResult<()>)]) -> DeResult<()> {
        if let Some(m) = self.obj {
            for (k, v) in m {
                if let Some((_, _, f)) = fields.iter().find(|(n, _, _)| n == k) {
                    f(v)?;
                }
            }
            for (name, required, _) in fields {
                if *required && !m.contains_key(*name) {
                    return Err(format!("missing field `{}`", name));
                }
            }
            Ok(())
        } else {
            let s = self.seq.unwrap();
            for (i, (_, _, f)) in fields.iter().enumerate() {
                match s.get(i) {
                    Some(v) => f(v)?,
                    None => {
                        if fields[i].1 {
                            return Err(format!(
                                "invalid length {}, expected struct {} with {} elements",
                                s.len(),
                                self.name,
                                self.total
                            ));
                        }
                    }
                }
            }
            Ok(())
        }
    }
}

fn opt_validator<'f>(f: &'f dyn Fn(&Value) -> DeResult<()>) -> impl Fn(&Value) -> DeResult<()> + 'f {
    move |v: &Value| if v.is_null() { Ok(()) } else { f(v) }
}

fn de_position(v: &Value) -> DeResult<(u32, u32)> {
    let s = sv(v, "Position", 2)?;
    let line_f = |x: &Value| de_u32(x).map(|_| ());
    let char_f = |x: &Value| de_u32(x).map(|_| ());
    s.validate(&[("line", true, &line_f), ("character", true, &char_f)])?;
    Ok((de_u32(s.req(0, "line")?)?, de_u32(s.req(1, "character")?)?))
}

fn de_text_document_identifier(v: &Value) -> DeResult<url::Url> {
    let s = sv(v, "TextDocumentIdentifier", 1)?;
    let uri_f = |x: &Value| de_url(x).map(|_| ());
    s.validate(&[("uri", true, &uri_f)])?;
    de_url(s.req(0, "uri")?)
}

struct CursorParams {
    line: u32,
    character: u32,
    uri: url::Url,
}

fn de_cursor_params(v: &Value) -> DeResult<CursorParams> {
    let s = sv(v, "CursorRequest", 2)?;
    let pos_f = |x: &Value| de_position(x).map(|_| ());
    let doc_f = |x: &Value| de_text_document_identifier(x).map(|_| ());
    s.validate(&[("position", true, &pos_f), ("document", true, &doc_f)])?;
    let (line, character) = de_position(s.req(0, "position")?)?;
    let uri = de_text_document_identifier(s.req(1, "document")?)?;
    Ok(CursorParams { line, character, uri })
}

struct InitParams {
    root_uri: Option<url::Url>,
    workspace_folders: Vec<url::Url>,
}

fn de_workspace_folder(v: &Value) -> DeResult<url::Url> {
    let s = sv(v, "WorkspaceFolder", 2)?;
    let uri_f = |x: &Value| de_url(x).map(|_| ());
    let name_f = |x: &Value| de_string(x).map(|_| ());
    s.validate(&[("uri", true, &uri_f), ("name", true, &name_f)])?;
    de_url(s.req(0, "uri")?)
}

fn de_init_params(v: &Value) -> DeResult<InitParams> {
    let s = sv(v, "InitializeParams", 9)?;
    let pid_f = opt_validator(&|x: &Value| de_u32(x).map(|_| ()));
    let root_path_f = opt_validator(&|x: &Value| de_string(x).map(|_| ()));
    let root_uri_f = opt_validator(&|x: &Value| de_url(x).map(|_| ()));
    let init_opts_f = |_: &Value| Ok(());
    let caps_f = |x: &Value| match x {
        Value::Object(_) | Value::Array(_) => Ok(()),
        other => Err(format!("invalid type: {}, expected struct ClientCapabilities", other.unexpected())),
    };
    let trace_f = opt_validator(&|x: &Value| match x {
        Value::String(t) if t == "off" || t == "messages" || t == "verbose" => Ok(()),
        Value::String(t) => Err(format!("unknown variant `{}`, expected one of `off`, `messages`, `verbose`", t)),
        other => Err(format!("invalid type: {}, expected string", other.unexpected())),
    });
    let folders_f = opt_validator(&|x: &Value| match x {
        Value::Array(a) => {
            for f in a {
                de_workspace_folder(f)?;
            }
            Ok(())
        }
        other => Err(format!("invalid type: {}, expected a sequence", other.unexpected())),
    });
    let client_info_f = opt_validator(&|x: &Value| {
        let s = sv(x, "ClientInfo", 2)?;
        let name_f = |y: &Value| de_string(y).map(|_| ());
        let ver_f = opt_validator(&|y: &Value| de_string(y).map(|_| ()));
        s.validate(&[("name", true, &name_f), ("version", false, &ver_f)])
    });
    let locale_f = opt_validator(&|x: &Value| de_string(x).map(|_| ()));
    let token_f = opt_validator(&|x: &Value| match x {
        Value::Number(_) | Value::String(_) => Ok(()),
        other => Err(format!("invalid type: {}, expected number or string", other.unexpected())),
    });
    s.validate(&[
        ("processId", false, &pid_f),
        ("rootPath", false, &root_path_f),
        ("rootUri", false, &root_uri_f),
        ("initializationOptions", false, &init_opts_f),
        ("capabilities", true, &caps_f),
        ("trace", false, &trace_f),
        ("workspaceFolders", false, &folders_f),
        ("clientInfo", false, &client_info_f),
        ("locale", false, &locale_f),
        ("workDoneToken", false, &token_f),
    ])?;
    let root_uri = match s.opt(2, "rootUri") {
        None | Some(Value::Null) => None,
        Some(x) => Some(de_url(x)?),
    };
    let mut folders = Vec::new();
    if let Some(Value::Array(a)) = s.opt(6, "workspaceFolders") {
        for f in a {
            folders.push(de_workspace_folder(f)?);
        }
    }
    Ok(InitParams { root_uri, workspace_folders: folders })
}

fn uri_to_path(u: &url::Url) -> Option<PathBuf> {
    u.to_file_path().ok()
}

// ---------------------------------------------------------------------------
// Handlers
// ---------------------------------------------------------------------------

fn capabilities() -> Value {
    json::obj(vec![(
        "capabilities",
        json::obj(vec![
            (
                "textDocumentSync",
                json::obj(vec![
                    ("openClose", Value::Bool(true)),
                    ("change", Value::from_u64(2)),
                    ("save", Value::Bool(true)),
                ]),
            ),
            (
                "workspace",
                json::obj(vec![(
                    "workspaceFolders",
                    json::obj(vec![("supported", Value::Bool(true)), ("changeNotifications", Value::Bool(true))]),
                )]),
            ),
        ]),
    )])
}

fn handle_initialize(server: Arc<Server>, id: Id, params: Option<Value>, canceled: Arc<AtomicBool>) {
    let params = match params {
        None => {
            server.set_phase(Phase::Uninitialized);
            server.respond_err(&id, ERR_INVALID_PARAMS, "Missing params field");
            return;
        }
        Some(p) => p,
    };
    let parsed = match de_init_params(&params) {
        Ok(p) => p,
        Err(e) => {
            server.set_phase(Phase::Uninitialized);
            server.respond_err(&id, ERR_INVALID_PARAMS, &e);
            return;
        }
    };
    let mut roots: Vec<url::Url> = Vec::new();
    if let Some(r) = parsed.root_uri {
        roots.push(r);
    }
    roots.extend(parsed.workspace_folders);
    for r in roots {
        if canceled.load(Ordering::SeqCst) {
            return;
        }
        if let Some(p) = uri_to_path(&r) {
            let _ = server.backend.add_root(&p);
        }
    }
    if canceled.load(Ordering::SeqCst) {
        return;
    }
    server.backend.analyze_all();
    if canceled.load(Ordering::SeqCst) {
        return;
    }
    server.set_phase(Phase::Initialized);
    server.respond_ok(&id, &capabilities());
}

fn handle_shutdown(server: Arc<Server>, id: Id) {
    server.backend.stop_processes();
    server.set_phase(Phase::ShutDown);
    server.respond_ok(&id, &Value::Null);
}

fn handle_cursor(server: Arc<Server>, id: Id, params: Option<Value>) {
    let params = match params {
        None => {
            server.respond_err(&id, ERR_INVALID_PARAMS, "Missing params field");
            return;
        }
        Some(p) => p,
    };
    let cp = match de_cursor_params(&params) {
        Ok(p) => p,
        Err(e) => {
            server.respond_err(&id, ERR_INVALID_PARAMS, &e);
            return;
        }
    };
    let path = uri_to_path(&cp.uri).filter(|p| p.is_file());
    let res = server.backend.cursor(path, cp.line, cp.character);
    let result = json::obj(vec![
        ("decorations", Value::Array(res.decorations)),
        ("is_analyzed", Value::Bool(res.is_analyzed)),
        (
            "path",
            match &res.path {
                Some(p) => Value::String(p.to_string_lossy().into_owned()),
                None => Value::Null,
            },
        ),
        ("status", Value::str(res.status.name())),
    ]);
    server.respond_ok(&id, &result);
}

fn text_document_uri(params: &Value) -> Option<url::Url> {
    let td = params.get("textDocument")?;
    de_url(td.get("uri")?).ok()
}

fn handle_did_open(server: Arc<Server>, params: Value) {
    let td = match params.get("textDocument") {
        Some(t) => t,
        None => return,
    };
    let uri = match td.get("uri").map(de_url) {
        Some(Ok(u)) => u,
        _ => return,
    };
    if td.get("languageId").map(|v| de_string(v).is_err()).unwrap_or(true) {
        return;
    }
    if td.get("version").map(|v| de_i32(v).is_err()).unwrap_or(true) {
        return;
    }
    if td.get("text").map(|v| de_string(v).is_err()).unwrap_or(true) {
        return;
    }
    if let Some(path) = uri_to_path(&uri) {
        if path.is_file() {
            if server.backend.add_root(&path).is_err() {
                return;
            }
            server.backend.analyze_all();
        }
    }
}

fn handle_did_change(server: Arc<Server>, params: Value) {
    if text_document_uri(&params).is_none() {
        return;
    }
    if !matches!(params.get("contentChanges"), Some(Value::Array(_))) {
        return;
    }
    server.backend.clear_analyzed();
}

fn handle_did_change_workspace_folders(server: Arc<Server>, params: Value) {
    let event = match params.get("event") {
        Some(e) => e,
        None => return,
    };
    let added = match event.get("added") {
        Some(Value::Array(a)) => a,
        _ => return,
    };
    if !matches!(event.get("removed"), Some(Value::Array(_))) {
        return;
    }
    let mut uris = Vec::new();
    for f in added {
        match de_workspace_folder(f) {
            Ok(u) => uris.push(u),
            Err(_) => return,
        }
    }
    if uris.is_empty() {
        return;
    }
    for u in uris {
        if let Some(p) = uri_to_path(&u) {
            let _ = server.backend.add_root(&p);
        }
    }
    server.backend.analyze_all();
}

const REQUEST_METHODS: &[&str] = &["initialize", "shutdown", "rustowl/cursor"];
const NOTIFICATION_METHODS: &[&str] = &[
    "initialized",
    "exit",
    "textDocument/didOpen",
    "textDocument/didChange",
    "textDocument/didSave",
    "textDocument/didClose",
    "workspace/didChangeWorkspaceFolders",
    "$/cancelRequest",
];

// ---------------------------------------------------------------------------
// Main loop
// ---------------------------------------------------------------------------

pub fn run() -> ! {
    eprintln!("RustOwl v{}", crate::cli::VERSION);
    eprintln!("This is an LSP server. You can use --help flag to show help.");
    let transport = Arc::new(Transport::new());
    let backend = Backend::new(Some(transport.clone() as Arc<dyn ProgressClient>), true);
    let server = Arc::new(Server {
        transport: Arc::clone(&transport),
        backend,
        phase: Mutex::new(Phase::Uninitialized),
        inflight: Mutex::new(HashMap::new()),
    });
    let mut handlers: Vec<std::thread::JoinHandle<()>> = Vec::new();
    let mut reader = FrameReader { inner: std::io::stdin(), buf: Vec::new() };
    loop {
        let frame = reader.next_frame();
        let body = match frame {
            Frame::Eof => break,
            Frame::Error => {
                transport.send_error(&Id::Null, ERR_PARSE, "Parse error", None);
                break;
            }
            Frame::Message(b) => b,
        };
        if server.phase() == Phase::Exited {
            // tower-lsp stops servicing after `exit`; it never terminates on its own.
            loop {
                std::thread::park();
            }
        }
        let value = match json::parse(&body) {
            Ok(v) => v,
            Err(_) => {
                transport.send_error(&Id::Null, ERR_PARSE, "Parse error", None);
                break;
            }
        };
        let obj = match &value {
            Value::Object(m) => m,
            _ => {
                transport.send_error(&Id::Null, ERR_INVALID_REQUEST, "Invalid request", None);
                break;
            }
        };
        if obj.get("jsonrpc").and_then(|v| v.as_str()) != Some("2.0") {
            transport.send_error(&Id::Null, ERR_INVALID_REQUEST, "Invalid request", None);
            break;
        }
        let id = match obj.get("id") {
            None => None,
            Some(v) => match Id::from_value(v) {
                Some(i) => Some(i),
                None => {
                    transport.send_error(&Id::Null, ERR_INVALID_REQUEST, "Invalid request", None);
                    break;
                }
            },
        };
        let has_method = obj.contains_key("method");
        if !has_method && (obj.contains_key("result") || obj.contains_key("error")) {
            // response from the client
            if let Some(id) = id {
                let v = obj.get("result").cloned().unwrap_or(Value::Null);
                transport.deliver_response(&id, v);
            }
            continue;
        }
        let method = match obj.get("method") {
            None => String::new(),
            Some(Value::String(s)) => s.clone(),
            Some(_) => {
                transport.send_error(&Id::Null, ERR_INVALID_REQUEST, "Invalid request", None);
                break;
            }
        };
        let params = obj.get("params").cloned();
        handlers.retain(|h| !h.is_finished());
        match id {
            Some(id) => {
                if let Some(h) = dispatch_request(&server, id, &method, params) {
                    handlers.push(h);
                }
            }
            None => {
                if let Some(h) = dispatch_notification(&server, &method, params) {
                    handlers.push(h);
                }
            }
        }
    }
    for h in handlers {
        let _ = h.join();
    }
    std::process::exit(0);
}

fn dispatch_request(server: &Arc<Server>, id: Id, method: &str, params: Option<Value>) -> Option<std::thread::JoinHandle<()>> {
    let t = &server.transport;
    if !REQUEST_METHODS.contains(&method) {
        t.send_error(&id, ERR_METHOD_NOT_FOUND, "Method not found", Some(&Value::String(method.to_string())));
        return None;
    }
    let phase = server.phase();
    match method {
        "initialize" => {
            if phase != Phase::Uninitialized {
                t.send_error(&id, ERR_INVALID_REQUEST, "Invalid request", None);
                return None;
            }
            server.set_phase(Phase::Initializing);
            let canceled = server.begin_request(&id);
            let s = Arc::clone(server);
            Some(std::thread::spawn(move || handle_initialize(s, id, params, canceled)))
        }
        "shutdown" => {
            match phase {
                Phase::Uninitialized | Phase::Initializing => {
                    t.send_error(&id, ERR_NOT_INITIALIZED, "Server not initialized", None);
                    return None;
                }
                Phase::ShutDown | Phase::Exited => {
                    t.send_error(&id, ERR_INVALID_REQUEST, "Invalid request", None);
                    return None;
                }
                Phase::Initialized => {}
            }
            if let Some(p) = params {
                t.send_error(&id, ERR_INVALID_PARAMS, &format!("Unexpected params: {}", json::to_string(&p)), None);
                return None;
            }
            server.begin_request(&id);
            let s = Arc::clone(server);
            Some(std::thread::spawn(move || handle_shutdown(s, id)))
        }
        "rustowl/cursor" => {
            match phase {
                Phase::Uninitialized | Phase::Initializing => {
                    t.send_error(&id, ERR_NOT_INITIALIZED, "Server not initialized", None);
                    return None;
                }
                Phase::ShutDown | Phase::Exited => {
                    t.send_error(&id, ERR_INVALID_REQUEST, "Invalid request", None);
                    return None;
                }
                Phase::Initialized => {}
            }
            server.begin_request(&id);
            let s = Arc::clone(server);
            Some(std::thread::spawn(move || handle_cursor(s, id, params)))
        }
        _ => None,
    }
}

fn dispatch_notification(server: &Arc<Server>, method: &str, params: Option<Value>) -> Option<std::thread::JoinHandle<()>> {
    if !NOTIFICATION_METHODS.contains(&method) {
        return None;
    }
    match method {
        "exit" => {
            server.set_phase(Phase::Exited);
            server.cancel_all();
            return None;
        }
        "$/cancelRequest" => {
            if let Some(p) = params {
                if let Some(idv) = p.get("id") {
                    if let Some(id) = Id::from_value(idv) {
                        server.cancel(&id);
                    }
                }
            }
            return None;
        }
        _ => {}
    }
    if server.phase() != Phase::Initialized {
        return None;
    }
    let params = params?;
    let s = Arc::clone(server);
    match method {
        "textDocument/didOpen" => Some(std::thread::spawn(move || handle_did_open(s, params))),
        "textDocument/didChange" => Some(std::thread::spawn(move || handle_did_change(s, params))),
        "workspace/didChangeWorkspaceFolders" => {
            Some(std::thread::spawn(move || handle_did_change_workspace_folders(s, params)))
        }
        _ => None,
    }
}
