//! RustOwl: visualize ownership and lifetimes of Rust programs (LSP server and CLI).

mod backend;
mod cargo;
mod cli;
mod completions;
mod json;
mod logger;
mod lsp;
mod models;
mod toolchain;
mod url;
mod util;

use cli::{Command, ToolchainCommand};
use std::io::Write;
use std::path::PathBuf;

/// Print a message formatted like Rust's default panic hook.
pub fn panic_message(thread: &str, location: &str, msg: &str) {
    let mut out = format!("\nthread '{}' panicked at {}:\n{}\n", thread, location, msg);
    let bt = std::env::var("RUST_BACKTRACE").unwrap_or_default();
    if bt.is_empty() || bt == "0" {
        out.push_str("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n");
    }
    let stderr = std::io::stderr();
    let mut h = stderr.lock();
    let _ = h.write_all(out.as_bytes());
    let _ = h.flush();
}

/// Emulate a panic on the main thread: print the message and exit with 101.
pub fn panic_exit(thread: &str, location: &str, msg: &str) -> ! {
    panic_message(thread, location, msg);
    std::process::exit(101);
}

fn run_check(path: Option<String>, all_targets: bool, all_features: bool) -> ! {
    logger::init(3);
    let path: PathBuf = match path {
        Some(p) => PathBuf::from(p),
        None => std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
    };
    let backend = backend::Backend::with_flags(None, all_targets, all_features);
    match backend.add_root(&path) {
        Err(()) => std::process::exit(1),
        Ok(false) => {
            log_error!("rustowl", "Analyze failed");
            std::process::exit(1);
        }
        Ok(true) => {}
    }
    let handles = backend.analyze_all();
    for h in handles {
        let _ = h.join();
    }
    if backend.analyzed_file_count() > 0 {
        log_info!("rustowl", "Successfully analyzed");
        std::process::exit(0);
    } else {
        log_error!("rustowl", "Analyze failed");
        std::process::exit(1);
    }
}

fn run_clean() -> ! {
    logger::init(3);
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    if let Some(meta) = cargo::metadata_plain(&cwd) {
        let owl = meta.target_directory.join("owl");
        let _ = std::fs::remove_dir_all(&owl);
    }
    std::process::exit(0);
}

fn main() {
    let opts = cli::parse();
    match opts.command {
        Some(Command::Check { path, all_targets, all_features }) => run_check(path, all_targets, all_features),
        Some(Command::Clean) => run_clean(),
        Some(Command::Toolchain(sub)) => {
            logger::init(3);
            match sub {
                None => std::process::exit(0),
                Some(ToolchainCommand::Install { path, skip_rustowl_toolchain }) => {
                    let runtime = match path {
                        Some(p) => PathBuf::from(p),
                        None => toolchain::default_runtime_dir(),
                    };
                    match toolchain::install(&runtime, skip_rustowl_toolchain) {
                        Ok(()) => std::process::exit(0),
                        Err(()) => std::process::exit(1),
                    }
                }
                Some(ToolchainCommand::Uninstall) => {
                    toolchain::uninstall();
                    std::process::exit(0);
                }
            }
        }
        Some(Command::Completions(shell)) => {
            let script = completions::completion_script(shell);
            let stdout = std::io::stdout();
            let mut h = stdout.lock();
            let _ = h.write_all(script.as_bytes());
            let _ = h.flush();
            std::process::exit(0);
        }
        None => {
            if opts.version {
                if opts.quiet > 0 {
                    println!("v{}", cli::VERSION);
                } else {
                    println!("RustOwl v{}", cli::VERSION);
                }
                std::process::exit(0);
            }
            logger::init(2);
            lsp::run();
        }
    }
}
